code_files.file:
{
  top,
  lix,
  lib,
  dom,
  mod,
  ...
}: let
  inherit (lib.modules) mkIf;
  inherit (lix.options) mkModuleArgs;

  mk = scope: {
    config,
    pkgs,
    ...
  }: let
    module = mkModuleArgs {inherit config top dom mod scope pkgs;};
    opt = module.set.options.module;
    package = module.get.package;
    enable = module.get.config.module.enable or false;
  in {
    options = opt {enable = module.set.enable {default = true;};};
    config = mkIf enable (
      if scope == "core"
      then {environment.systemPackages = [package];}
      else {
        programs.${mod} = {
          inherit enable package;
        };
      }
    );
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  top,
  shared,
  path,
  registry,
  ...
}: let
  inherit (lix.options) mkEnable mkModuleArgs mkOption;
  inherit (lix.types) anything;
  inherit (lix.lists) last;

  name = last path;
  defaults = let
    staged = shared.ai.${name} or {};
    entry = registry.${name} or {};
  in {
    enable = staged.enable or false;
    provider = staged.provider or (entry.provider or null);
  };

  mk = scope: {config, ...}: let
    mod = mkModuleArgs {inherit config top scope path;};
    opt = mod.set.options.module;
  in {
    options = opt {
      enable = mkEnable {
        inherit name scope;
        default = defaults.enable;
      };

      provider = mkOption {
        type = anything;
        default = defaults.provider;
        description = "AI provider backing ${name}.";
      };
    };

    config = {};
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  top,
