}

{
  lix,
  top,
  host,
  ...
} @ args: let
  inherit (lix.modules) mkModules mkModuleArgs;
  inherit (lix.attrsets) attrByPath;
  inherit (lix.lists) elem toList;
  inherit (lix.strings) concatStringsSep;
  inherit (lix.options) mkOption;
  inherit (lix.types) package;

  # users = getInteractiveUsers host;

  data = {
    git = {
      group = "vcs";
      package = "gitFull";
    };
    lfs = {
      group = "vcs";
      package = "git-lfs";
    };
    gh = {
      group = "vcs";
      package = "gh";
    };
    jj = {
      group = "vcs";
      package = "jujutsu";
    };
    gitui = {
      group = "vcs";
      package = "gitui";
    };
    delta = {
      group = "vcs";
      package = "delta";
    };
    claude = {
      group = "ai";
      package = "claude-code";
    };
    codex = {
      group = "ai";
      package = "codex";
    };
    helix = {
      group = "editors";
      package = "helix";
    };
    vscode = {
      group = "editors";
      package = "vscode-fhs";
    };
    zed = {
      group = "editors";
      package = "zed-editor-fhs";
    };
    alacritty = {
      group = "terminals";
      package = "alacritty";
    };
    foot = {
      group = "terminals";
      package = "foot";
    };
    kitty = {
      group = "terminals";
      package = "kitty";
    };
    tmux = {
      group = "terminals";
      package = "tmux";
    };

    tailscale = {
      group = "connectivity";
      package = "tailscale";
    };
  };

  inner = mkModules (args
    // {
      base = ./.;
      inherit data;
      extraArgs = {
        mkArgs = {
          config,
          path,
          pkgs ? {},
          scope ? "core",
        }: let
          module = mkModuleArgs {
            inherit config top scope path pkgs host;
            lib = lix;
          };
          inherit (module) get set;
          inherit (get) name user hostEntry userEntry;

          entry = data.${name} or {};
          group = entry.group or name;
          # domain = head path;
          # hostEntry = attrByPath [domain group name] {} host;
          # userEntry = attrByPath [domain group name] {} user;
          # pkgName may be a flat string ("gitFull") or a nested path
          # (["llm-agents" "claude-code"]) — normalize to a list either way.
          pkg = {
            spec = get.package;
            path = toList pkg.spec;
            name = concatStringsSep "." pkg.path;
          };
        in
          module
          // {
            fields = {
              enable = set.enable {
                default =
                  hostEntry.enable or (
                    userEntry.enable or (
                      elem group (host.functionalities or [])
                      || elem group (user.functionalities or [])
                    )
                  );
              };
              package = mkOption {
                type = package;
                default = attrByPath pkg.path null pkgs;
                description = "Package of '${pkg.name}' for ${scope}.";
              };
            };
          };
      };
    });
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  lib,
  registry,
  mkArgs,
  ...
}: let
  name = "delta";
  pkgName = registry.${name}.package;
  inherit (lib.modules) mkDefault mkIf;
in {
  core = {
    config,
    pkgs,
    ...
  }: let
    scope = "core";
    inherit (mkArgs {inherit config scope;}) cfg;
  in {
    config = mkIf cfg.enable {
      environment.systemPackages = [pkgs.${pkgName}];
    };
  };

  home = {
    config,
    pkgs,
    ...
  }: let
    scope = "home";
    inherit (mkArgs {inherit config scope;}) cfg opt mkEnableMod;
  in {
    options = opt {${name}.enable = (mkEnableMod {inherit name;}).true;};
    config = mkIf cfg.enable {
      programs.${name} = {
        enable = mkDefault true;
        package = mkDefault pkgs.${pkgName};
        enableGitIntegration = mkDefault true;
        options = {
          navigate = mkDefault true;
          side-by-side = mkDefault true;
        };
      };
    };
  };
}

{
  lix,
  top,
  lib,
  dom,
  mod,
  ...
}: let
  inherit (lib.modules) mkIf;
  inherit (lix.options) mkModuleArgs;

  mk = scope: {
    config,
    pkgs,
    ...
  }: let
    module = mkModuleArgs {inherit config top dom mod scope pkgs;};
    opt = module.set.options.module;
    package = module.get.package;
    enable = module.get.config.module.enable or false;
  in {
    options = opt {enable = module.set.enable {default = config.${top}.interface.protocol.wayland;};};
    config = mkIf enable (
      if scope == "core"
      then {environment.systemPackages = [package];}
      else {programs.${mod} = {inherit enable package;};}
    );
  };
in {
  core = mk "core";
  home = mk "home";
}

