        default = "noctalia-shell";
        description = "Command used by compositor-specific startup hooks.";
      };
      onHyprland = (mkEnable {name = "Noctalia on Hyprland";}).true;
      onNiri = (mkEnable {name = "Noctalia on Niri";}).true;
    };

    config = mkIf cfg.enable {
      programs.noctalia = {
