      opt = module.set.options.module;
      inherit mkEnableMod;
    };

  inner = ingest (args
    // {
      base = ./.;
      declareRegistry = false;
      extraArgs = {inherit packages mkArgs;};
    });
in {
  core = [];
  home = inner.home-manager.sharedModules or [];
}

