{
  lix,
  path,
  mkArgs,
  ...
}: let
  inherit (lix.attrsets) recursiveUpdate;
  inherit (lix.modules) mkMerge mkIf;
  inherit (lix.options) mkEnableOption mkOption;
  inherit (lix.types) enum;

  mk = scope: {
    config,
    options,
    pkgs,
    osConfig ? {},
    ...
  }: let
    inherit (mkArgs {inherit config options osConfig path pkgs scope;}) evaluated get set;
    inherit (get) apiOr cfg name prettyName;
    inherit (set) opt;
  in {
    options =
      recursiveUpdate
      evaluated.options
      (opt {
        configType = mkOption {
          type = enum ["hyprlang" "lua"];
          default = let
            derived = apiOr "configType";
            default = "hyprlang";
          in
            if derived != null
            then derived
            else default;
          description = "Home Manager Hyprland configuration format.";
        };
        enableAddons =
          mkEnableOption "Whether to enable sane ${prettyName} addons"
          // {default = true;};
        enableRules =
          mkEnableOption "Whether to enable sane ${prettyName} window rules"
          // {default = true;};
      });

    config = mkMerge [
      evaluated.config
      (mkIf (cfg.enable or false) (
        if scope == "core"
        then {programs.${name} = {withUWSM = cfg.uwsm.enable;};}
        else {
          wayland.windowManager.${name} = mkMerge [
            {
              # imports = [./settings ./submaps];
              configType = cfg.configType;
            }
            (import ./settings {inherit lix cfg;})
            # (import ./submaps)
          ];
        }
      ))
    ];

    imports =
      if scope == "home"
      then [./addons]
      else [];
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  cfg,
  lix,
  ...
}: let
  inherit (lix.modules) mkIf;
  # inherit (lix.hardware.display) mkHyprlandMonitors;
  # inherit (lix.schema.io) mkHyprKeybindings;

  mod = cfg.bindings.modifier;
in {
  # monitor = mkHyprlandMonitors {inherit host;};

  input = {
    touchpad = {
      scroll_factor = 0.3;
      natural_scroll = false;
      tap-and-drag = true;
    };
    follow_mouse = false;
    accel_profile = "flat";
    kb_options = mkIf cfg.bindings.swapCapsEscape "caps:swapescape";
  };

  bind = mkHyprKeybindings keyboard;

  bindr = ["${mod}, SUPER_L, exec, ${apps.launcher.primary.command}"];

  #~@ Locked binds - active even when screen is locked
  bindl = [
    ", XF86AudioPlay, exec, playerctl play-pause"
    ", XF86AudioPrev, exec, playerctl previous"
    ", XF86AudioNext, exec, playerctl next"
    ", XF86AudioMute, exec, wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"
    ", XF86AudioMicMute, exec, wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"
  ];

  #~@ Locked + repeating
  bindle = [
    ", XF86AudioRaiseVolume, exec, wpctl set-volume -l '1.0' @DEFAULT_AUDIO_SINK@ 5%+"
    ", XF86AudioLowerVolume, exec, wpctl set-volume -l '1.0' @DEFAULT_AUDIO_SINK@ 5%-"
    ", XF86MonBrightnessDown, exec, brightnessctl set 5%-"
    ", XF86MonBrightnessUp, exec, brightnessctl set +5%"
  ];

  bindm = [
    "${mod}, mouse:272, movewindow"
    "${mod}, mouse:273, resizewindow"
    "${mod} SHIFT, mouse:272, resizewindow"
  ];

  binde = [
    "${mod}, EQUAL, splitratio, 0.25"
    "${mod} SHIFT, EQUAL, splitratio, 0.015"
    "${mod}, MINUS, splitratio, -0.25"
    "${mod} SHIFT, MINUS, splitratio, -0.015"
  ];
}

