  # ╔════════════════════════════════════════════════╗
  # ╠ LAYOUT & BORDERS                               ╣
  # ╚════════════════════════════════════════════════╝
  general = {
    layout = "dwindle";
    gaps_in = 4;
    gaps_out = 8;
    border_size = 2;
    resize_on_border = true;
    "col.active_border" = "rgba(b4befeaf) rgba(6c7086af) 45deg";
    "col.inactive_border" = "rgba(313244ff)";
  };

  dwindle = {
    force_split = 2;
    preserve_split = true;
  };

  master = {
    new_status = "master";
    orientation = "left";
    mfact = 0.55;
  };

  # ╔════════════════════════════════════════════════╗
  # ╠ MISCELLANEOUS SETTINGS                         ╣
  # ╚════════════════════════════════════════════════╝
  general = {
    sensitivity = 1.0;
    allow_tearing = false;
  };
  debug.disable_logs = false;
  misc = {
    disable_autoreload = false;
    force_default_wallpaper = 0;
    vrr = 1;
  };
}

