{specialWorkspaceNames ? [], ...}: let
  gap = "4";
  border = "0";
  specialRule = name: "special:${name}, gapsout:${gap}, gapsin:${gap}, bordersize:0, shadow:false";
in {
  workspace =
    [
      "w[tv1], gapsout:${gap}, gapsin:${gap}, bordersize:${border}"
      "f[1], gapsout:${gap}, gapsin:${gap}, bordersize:${border}"
    ]
    ++ map specialRule specialWorkspaceNames;

  windowrule = [
    "border_size 0, match:float 0, match:workspace w[tv1]s[false]"
    "rounding 0, match:float 0, match:workspace w[tv1]s[false]"
  ];
}

{lib, ...}: let
  inherit (lib.strings) concatStringsSep;
  toRegex = list: "^(${concatStringsSep "|" list})$";
  common = [
    "ags"
    "calendar"
    "notifications"
    "osd"
    "system-menu"
    "anyrun"
    "vicinae"
    "caelestia:launcher"
  ];
  panels = [
    "bar"
    "gtk-layer-shell"
  ];
  layers = common ++ panels;
in {
  layerrule = [
    "blur on, match:namespace ${toRegex layers}"
    "xray on, match:namespace ${toRegex panels}"
    "ignore_alpha 0.2, match:namespace ${toRegex panels}"
    "ignore_alpha 0.5, match:namespace ${toRegex (common ++ ["music"])}"
  ];
}

{
  lib,
  keyboard,
  ...
}: let
  inherit (lib.lists) elem flatten range;
  inherit (keyboard) mod;
  cat = lib.lists.concatMap;
  mat = lib.attrsets.mapAttrsToList;

  numWorkspaces = map toString (range 0 9);
  fWorkspaces = map (n: "F${toString n}") (range 1 12);

  directions = let
    left = "l";
    right = "r";
    up = "u";
    down = "d";
  in {
    inherit
      left
      right
      up
      down
      ;
    h = left;
    l = right;
    k = up;
    j = down;
  };

  mkWorkspaceVariant = {
    command,
    class,
    workspace,
    key,
    extraMod ? "",
    workdir ? null,
  }: let
    cmd =
      if workdir != null
      then
        if
          (elem class [
            "foot"
            "feet"
            "com.mitchellh.ghostty"
            "yazi"
          ])
        then ''${command} --working-directory="${workdir}"''
        else "cd ${workdir} && ${command}"
      else command;

    moveScript = "for i in {1..10}; do sleep 0.3; hyprctl dispatch movetoworkspacesilent 'special:${workspace},class:^(${class})$' 2>/dev/null | grep -q 'ok' && break; done";
    modStr = "${mod}${lib.optionalString (extraMod != "") " ${extraMod}"}";
  in {
    bind = "${modStr},${key},togglespecialworkspace,${workspace}";
    exec =
      if (class == "microsoft-edge")
      then ''sh -c "${cmd} & ${moveScript}"''
      else "[workspace special:${workspace} silent] ${cmd}";
    rule = [
      "workspace special:${workspace} silent, match:class ^(${class})$"
      "suppress_event fullscreen maximize, match:class ^(${class})$"
    ];
  };

  mkWorkspace = name: {
    key,
    primary,
    secondary,
    workdir ? null,
  }: [
    (mkWorkspaceVariant {
      inherit (primary) command class;
      inherit key workdir;
      workspace = name;
      extraMod = "ALT";
    })
    (mkWorkspaceVariant {
      inherit (secondary) command class;
      inherit key workdir;
      workspace = "${name}Alt";
      extraMod = "ALT SHIFT";
    })
  ];

  specialWorkspaces = {
    # browser = {
    #   inherit (browser) primary secondary;
    #   key = "B";
    # };
    # editor = {
    #   inherit (editor) primary secondary;
    #   key = "C";
    # };
    # explorer = {
    #   inherit (explorer) primary secondary;
    #   key = "E";
    #   workdir = "$HOME";
    # };
    # terminal = {
    #   inherit (terminal) primary secondary;
    #   key = "GRAVE";
    #   workdir = "$DOTS";
    # };
  };

  allVariants = flatten (mat mkWorkspace specialWorkspaces);

  mkDirectionalBinds = {
    modifier ? mod,
    action,
  }:
    mat (key: dir: "${modifier},${key},${action},${dir}") directions;
in {
  specialWorkspaceNames = flatten (
    mat (name: _: [
      name
      "${name}Alt"
    ])
    specialWorkspaces
  );
  windowrule = cat (v: v.rule) allVariants;
  exec-once = map (v: v.exec) allVariants;

  bind = flatten [
    (map (v: v.bind) allVariants)

    (cat (
        n: let
          ws =
            if n == "0"
            then "10"
            else n;
        in [
          "${mod},${n},workspace,${ws}"
          "${mod} SHIFT,${n},movetoworkspacesilent,${ws}"
        ]
      )
      numWorkspaces)

    (cat (n: [
        "${mod},${n},workspace,name:${n}"
        "${mod} SHIFT,${n},movetoworkspacesilent,name:${n}"
      ])
      fWorkspaces)

    (mkDirectionalBinds {action = "movefocus";})
    (mkDirectionalBinds {
      modifier = "${mod} SHIFT";
      action = "swapwindow";
    })
    (mkDirectionalBinds {
      modifier = "${mod} CTRL";
      action = "movewindoworgroup";
    })
    (mkDirectionalBinds {
      modifier = "${mod} ALT";
      action = "focusmonitor";
    })
    (mkDirectionalBinds {
      modifier = "${mod} ALT SHIFT";
      action = "movecurrentworkspacetomonitor";
    })
  ];
}

{
  misc = {
    #? disable auto polling for config file changes
    disable_autoreload = true;

    force_default_wallpaper = 0;

    #? Variable refresh rate (effective depending on hardware)
