      // optionalAttrs (actions.closeWindow.description != null) {
        "Mod+Q" = {
          action.close-window = [];
          hotkey-overlay.title = "Close focused window";
        };
      }
      // optionalAttrs (enabled ? lock)
      (withTitle "Mod+Ctrl+L" "Lock session" enabled.lock)
      // optionalAttrs (actions.showKeybinds.description != null) {
        "Mod+Ctrl+Slash" = {
          action.show-hotkey-overlay = [];
          hotkey-overlay.title = "Show common keybinds";
        };
      }
      // optionalAttrs (enabled ? screenshot) {
        "Mod+Print" = {
          action.spawn = ["sh" "-lc" enabled.screenshot.command];
          hotkey-overlay.title = "Region screenshot → clipboard";
        };
      };
  });
}

{
  lix,
  path,
  mkArgs,
  ...
}: let
  inherit (lix.attrsets) genAttrs recursiveUpdate;
  inherit (lix.options) mkEnableOption mkOption;
  inherit (lix.types) nullOr str submodule;

  mk = args: mkArgs ({inherit extraArgs path;} // args);
  extraArgs = {fallbackConfig = "config/niri/config.kdl";};

  mkActionOption = description: overrides:
    mkOption {
      type = submodule {
        options = {
          command = mkOption {
            type = nullOr str;
            default = overrides.command or null;
            description = "Shell command for the ${description} action.";
          };
          description = mkOption {
            type = str;
            default = overrides.description or description;
            description = "Human-readable label for the ${description} action.";
          };
        };
      };
      default = {};
      description = "Shared semantic Niri action for ${description}.";
    };

  mkOptions = overrides: {
    fallbackConfig = mkOption {
      type = str;
      default =
        if (overrides.fallbackConfig or null) != null
        then overrides.fallbackConfig
        else extraArgs.fallbackConfig;
      description = "Path to Niri fallback KDL configuration.";
    };

    semanticKeybinds =
      mkEnableOption "modular semantic keybind layer for Niri"
      // {default = true;};

    actions = {
      secondaryLauncher = mkActionOption "secondary launcher" {
        command = "fuzzel";
        description = "Open Fuzzel";
      };
      showKeybinds = mkActionOption "show keybinds/help" {
        command = "dots-common-keybinds";
        description = "Show common keybinds";
      };
      terminal = mkActionOption "terminal" {
        command = "foot";
        description = "Open terminal";
      };
      scratchpadTerminal = mkActionOption "scratchpad/quake terminal" {
        command = "foot --app-id dots-scratchpad";
        description = "Open scratchpad terminal";
      };
      primaryBrowser = mkActionOption "primary browser" {
        command = "zen";
        description = "Open primary browser";
      };
      secondaryBrowser = mkActionOption "secondary browser" {
        command = "chromium";
        description = "Open secondary browser";
      };
      visualTools = mkActionOption "visual tools" {
        command = "vicinae open || fuzzel";
        description = "Open visual tools";
      };
      fileManager = mkActionOption "file manager" {
        command = "xdg-open $HOME";
        description = "Open file manager";
      };
      editor = mkActionOption "editor" {
        command = "code";
        description = "Open editor";
      };
      fullscreen = mkActionOption "fullscreen" {description = "Toggle fullscreen";};
      logout = mkActionOption "logout/exit session" {description = "Exit compositor session";};
      closeWindow = mkActionOption "close window" {description = "Close focused window";};
      lock = mkActionOption "lock" {
        command = "loginctl lock-session";
        description = "Lock session";
      };
      screenshot = mkActionOption "screenshot" {
        command = ''grim -g "$(slurp)" - | wl-copy'';
        description = "Take a screenshot";
      };
    };
  };
in {
  core = {
    config,
    options,
    pkgs,
    ...
  }: let
    inherit (mk {inherit config options pkgs;}) apiOr set evaluated;
  in {
    options = recursiveUpdate evaluated.options (set.options.module (mkOptions (genAttrs ["fallbackConfig"] apiOr)));
    inherit (evaluated) config;
  };

  home = {
    config,
    options,
    pkgs,
    osConfig,
    ...
  }: let
    scope = "home";
    mod = mk {inherit config options osConfig pkgs scope;};
    inherit (mod) apiOr set evaluated;
  in {
    imports = [./bindings.nix ./packages.nix];
    options = recursiveUpdate evaluated.options (set.options.module (mkOptions (genAttrs ["fallbackConfig"] apiOr)));
    inherit (evaluated) config;
  };
}

{
  config,
  lib,
  pkgs,
  top,
  ...
}: let
  cfg = config.${top}.interface.backends.niri;

  inherit (lib.meta) getExe;
  inherit (lib.modules) mkIf;
in {
  config = mkIf (cfg.enable && (cfg.semanticKeybinds or false)) {
    home.packages = with pkgs; [
      (
        writeShellScriptBin "dots-common-keybinds" ''
          ${getExe libnotify} "Common desktop keybinds" "$(cat <<'HELP'
          Win+Space: secondary launcher
          Win+Enter: terminal
          Win+`: scratchpad terminal
          Win+B: primary browser
          Win+Alt+B: secondary browser
          Win+V: visual tools launcher
          Win+F: file manager
          Win+E: editor
          Alt+Enter / Win+Ctrl+F: fullscreen
          Win+Q: close focused window
          Win+Ctrl+L: lock session
          Win+Ctrl+Q: exit Niri
          Print: screenshot
          Win+Print: region screenshot to clipboard
          Win+Shift+/: Niri hotkey overlay
          HELP
          )"
        ''
      )
      brightnessctl
      grim
      libnotify
      slurp
      wl-clipboard
      wireplumber
    ];
  };
}

{lix, ...} @ args: let
  inherit (lix.modules) mkModules mkModuleArgs;

  moduleArgs = {
    inherit extraArgs;
    base = ./.;
    excludes = [
      # "backend"
      # "frontend"
      # "protocol"
      # "session"
    ];
  };

  extraArgs = {
    mkArgs = {
      config,
      osConfig ? {},
      options ? {},
      path,
      scope ? "core",
      pkgs ? {},
    }:
      mkModuleArgs {
        inherit
          config
          options
          osConfig
          path
          pkgs
          scope
          ;
      };
  };
in
  mkModules (args // moduleArgs)

{
  mkChild,
  path,
  ...
}: let
  targets = [
    ["programs" "caelestia-shell"]
    ["programs" "caelestia"]
  ];
in {
  core = mkChild {
    inherit path targets;
  };

  home = mkChild {
    inherit path targets;
    scope = "home";
  };
}

{
  lix,
  mkChild,
  path,
  ...
}: let
  inherit (lix.attrsets) hasAttrByPath optionalAttrs;
  inherit (lix.options) mkEnableOption;
  inherit (lix.lists) elem;
  inherit (lix.types) isList isString;

  mkOptions = child: {
    isRequired =
      mkEnableOption "Whether this ${child.get.name} is selected by the host or user"
      // {
        default = let
          target = child.get.config.parent.selected;
        in
          if isList target
          then elem child.get.name target
          else if isString target
          then target == child.get.name
          else false;
      };

    needsNiri =
      mkEnableOption "Whether this ${child.get.name} is selected by the host or user"
      // {default = child.get.config.domain.backends.niri.enable or false;};
  };
in {
  core = mkChild {
    inherit path mkOptions;
    target = ["programs" "dms-shell"];
  };

  home = mkChild {
    inherit path mkOptions;
    scope = "home";
    target = ["programs" "dank-material-shell"];
    extraConfig = {
      config,
      cfg,
      enabled,
      options,
      ...
    }: let
      target = ["programs" "dank-material-shell" "niri"];
      targetExists = hasAttrByPath target options;
      includesEnable =
        if targetExists
        then config.programs.dank-material-shell.niri.includes.enable or true
        else true;
    in
      optionalAttrs targetExists {
        programs.dank-material-shell.niri = {
          enableKeybinds = enabled && (cfg.needsNiri or false) && !includesEnable;
          enableSpawn = enabled && (cfg.needsNiri or false);
        };
      };
  };
}

{
  lix,
  top,
  host,
  path,
  ...
} @ args: let
  inherit (lix.api) getInteractiveUsers;
  inherit (lix.api) interfaceRegistry;
  inherit (lix.registry) select;
  inherit
    (lix.attrsets)
    attrByPath
    foldMerge
    hasAttr
    hasAttrByPath
    mapAttrs
    namesOf
    optionalAttrs
    recursiveUpdate
    setAttrByPath
    valuesOf
    ;
  inherit (lix.lists) elem elemAt filter findFirst length;
  inherit (lix.modules) mkDefault mkIf mkMerge mkModules mkModuleArgs;
  inherit (lix.options) mkEnable mkOption;
  inherit (lix.types) attrs enum nullOr package submodule;
  here = path;
  aliases = {
    dms = "dank-material";
  };

  frontendValues = [
    "dms"
    "dank-material"
    "noctalia"
    "caelestia"
    "gnome"
    "plasma"
    "cosmic"
  ];
  normalize = frontend:
    if frontend == null
    then null
    else aliases.${frontend} or frontend;

  registryFrontendOf = spec: let
    names = namesOf (select {inherit spec;});
    value =
      if length names > 0
      then elemAt names 0
      else null;
    env = optionalAttrs (value != null) (interfaceRegistry.${value} or {});
  in
    normalize (env.frontend or null);

  selectedFrontend = spec: normalize ((spec.interface or {}).frontend or (registryFrontendOf spec));
  materialize = selected:
    mapAttrs
    (_: extra: {enable = true;} // extra)
    (foldMerge (map (name: setAttrByPath [name] {}) (filter (name: name != null) selected)));
  required = let
    main = [
      (selectedFrontend host)
    ];
    isDesktopHost = elem (host.type or "desktop") ["desktop" "laptop"];
    userSelections =
      if isDesktopHost
      then map selectedFrontend (valuesOf (getInteractiveUsers host))
      else [];
  in {
    core = materialize (main ++ userSelections);
    home = user:
      materialize (
        main
        ++ (
          if isDesktopHost
          then [(selectedFrontend user)]
          else []
        )
      );
  };
  activeBackendNames = namesOf (select {spec = host;});

  primaryBackend =
    if length activeBackendNames > 0
    then elemAt activeBackendNames 0
    else null;

  primaryEnv =
    if primaryBackend != null
    then interfaceRegistry.${primaryBackend} or {}
    else {};

  registryFrontend = registryFrontendOf host;

  isWayland = primaryEnv.protocol or null == "wayland";

  mkMod = {
    config,
    options ? {},
    scope ? "core",
    pkgs,
    path ? here,
  }: let
    users = getInteractiveUsers host;
    module = mkModuleArgs {inherit top config path scope pkgs options users;};
    inherit (module.get) name prettyName;
    opt = module.set.options.module;
    fields = {
      enable = mkEnable {
        inherit name scope;
        default =
          if scope == "home"
          then hasAttr name (required.home module.user)
          else hasAttr name required.core;
      };
      package = mkOption {
        type = nullOr package;
        default = attrByPath [name] (attrByPath ["${name}-shell"] null pkgs) pkgs;
        description = "Package backing the ${prettyName} frontend layer.";
      };
    };
  in {
    inherit fields;
    args = {inherit module;};
    options = module.set.options.module fields;
    config = mkMerge [
      (opt {enable = mkDefault fields.enable.default;})
      (mkIf (fields.package.default != null) (opt {package = mkDefault fields.package.default;}))
    ];
  };

  moduleArgs = {
    base = ./.;
    excludes = [];
    declareRegistry = false;
    childPath = path;
    extraArgs = let
      buildChild = {
        config,
        options ? {},
        path,
        pkgs ? {},
        scope ? "core",
        osConfig ? config,
        defaults ? {},
      }: let
        mod = mkMod {inherit config path pkgs scope options;};
        module = mod.args.module;
        cfgOr = key:
          attrByPath
          ([top] ++ path ++ [key]) (defaults.${key} or null)
          osConfig;
        enableTarget = {
          options,
          enabled,
          target ? null,
          targets ? [],
        }: let
          target' =
            if target != null && hasAttrByPath target options
            then target
            else findFirst (candidate: hasAttrByPath candidate options) null targets;
          hasSub = key: target' != null && hasAttrByPath (target' ++ [key]) options;
          frontendCfg = optionalAttrs (hasSub "enable") {enable = enabled;};
        in
          optionalAttrs (target' != null && frontendCfg != {}) (setAttrByPath target' frontendCfg);
      in
        module
        // {
          inherit cfgOr enableTarget;
          inherit (mod) options config;
        };
      mkChild = {
        path,
        scope ? "core",
        target ? null,
        targets ? [],
        mkOptions ? (_: {}),
        extraConfig ? (_: {}),
      }: {
        config,
        options,
        pkgs,
        ...
      }: let
        child = buildChild {inherit config options path pkgs scope;};
        cfg = child.get.config.module;
        enabled = cfg.enable or (cfg.isRequired or false);
        extraOptions = mkOptions child;
      in {
        options =
          if extraOptions == {}
          then child.options
          else recursiveUpdate child.options (child.set.options.module extraOptions);
        config = mkMerge [
          child.config
          (child.enableTarget {inherit options enabled target targets;})
          (extraConfig {inherit child cfg enabled config options pkgs;})
        ];
      };
    in {
      inherit mkChild;
      mkArgs = buildChild;
    };
  };

  mk = scope: {config, ...}: let
    mod = mkModuleArgs {
      inherit config top scope;
      path = ["interface"];
    };
    opt = mod.set.options.module;
    cfg = mod.get.config.module;
  in {
    options = opt {
      frontend = mkOption {
        type = submodule {
          freeformType = attrs;
          options.selected = mkOption {
            type = nullOr (enum frontendValues);
            apply = normalize;
            default = normalize (host.interface.frontend or registryFrontend);
            description = "Graphical frontend layer for the selected desktop session backend. `dms` is accepted as an alias for `dank-material`.";
          };
        };
        default = {};
        description = "Graphical frontend configuration.";
      };
    };
    config.assertions = [
      {
        assertion = cfg.frontend.selected == null || primaryBackend != null;
        message = "interface.frontend requires an active interface.backend.";
      }
      {
        assertion = cfg.frontend.selected == null || isWayland;
        message = "The selected interface.frontend requires a Wayland session.";
      }
      {
        assertion = cfg.frontend.selected == null || cfg.frontend.selected == registryFrontend;
        message = "interface.frontend.selected (${toString cfg.frontend.selected}) doesn't match the frontend the registry declares for '${toString primaryBackend}' (${toString registryFrontend}).";
      }
    ];
  };

  inner = mkModules (args // moduleArgs);
in {
  core.imports = (inner.imports or []) ++ [(mk "core")];
  home.imports = (inner.home-manager.sharedModules or []) ++ [(mk "home")];
}

{
  mkChild,
  path,
  ...
}: {
  core = mkChild {
    inherit path;
    targets = [
      ["programs" "noctalia"]
      ["programs" "noctalia-shell"]
    ];
  };

  home = mkChild {
    inherit path;
    scope = "home";
    targets = [
      ["programs" "noctalia"]
      ["programs" "noctalia-shell"]
    ];
  };
}

{
  lix,
  top,
  host,
  api,
  path,
  ...
}: let
  inherit (lix.attrsets) attrByPath optionalAttrs;
  inherit (lix.lists) any optionals;
  inherit (lix.modules) mkIf mkModuleArgs;
  inherit (lix.options) mkEnableOption;
  inherit (api) interfaceBackends interfaceRegistry;

  names = interfaceBackends host;
  values = interfaceRegistry;

  per = protocol: any (name: attrByPath [name "protocol"] null values == protocol) names;
  wantsXwaylandSatellite = any (name: attrByPath [name "needsXwaylandSatellite"] false values) names;

  mk = scope: {
    config,
    pkgs,
    ...
  }: let
    inherit (mkModuleArgs {inherit config top scope path;}) get set;
    inherit (get) cfg;
    inherit (set) opt;
  in {
    options = opt {
      x11 = mkEnableOption "X11 support" // {default = per "x11";};
      wayland = mkEnableOption "Wayland support" // {default = per "wayland";};
    };

    config = optionalAttrs (scope == "core") {
      services.xserver.enable = cfg.x11;
      programs.uwsm.enable = cfg.wayland;
      environment = {
        sessionVariables = mkIf cfg.wayland {NIXOS_OZONE_WL = "1";};
        systemPackages = with pkgs;
          optionals cfg.wayland [cage libsecret wayland-utils wl-clipboard-rs]
          ++ optionals wantsXwaylandSatellite [xwayland-satellite];
      };
    };
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  top,
  host,
  api,
  path,
  ...
}: let
  inherit (lix.api) getAdminUsers;
  inherit (lix.attrsets) attrValues;
  inherit (lix.lists) elem elemAt first length;
  inherit (lix.modules) mkIf mkModuleArgs;
  inherit (lix.options) mkEnableOption mkOption;
  inherit (lix.registry) resolve;
  inherit (lix.types) enum nullOr str;

  resolveBackends = spec:
    resolve {
      spec = spec;
      registry = api.interfaceRegistry;
      inherit top;
    };

  login = (host.interface or {}).login or {};
  primary = host.users.primary.value or null;
  admins = attrValues (getAdminUsers host);

  fallback = {
    admin =
      if primary != null && (primary.role or "") == "administrator"
      then primary
      else if length admins > 0
      then elemAt admins 0
      else primary;
    user =
      if fallback.admin != null
      then fallback.admin.name
      else null;
  };

  auto = {
    enable = login.autoLogin.enable or false;
    user = login.autoLogin.user or fallback.user;
  };

  primaryBackend = spec: first (resolveBackends spec);

  sessionName = env:
    if env == null
    then null
    else login.sessions.${env.name} or env.session or env.name;

  defaultSession = spec: sessionName (primaryBackend spec);

  displayManagerFor = spec: let
    env = primaryBackend spec;
  in
    login.manager or host.interface.displayManager or (
      if env != null
      then env.greeter or "regreet"
      else "none"
    );

  greeterValues = map (env: env.greeter or "none") (attrValues api.interfaceRegistry);
  managerEnumValues = ["none" "dms" "regreet"] ++ greeterValues;

  opts = manager: session: {
    manager = mkOption {
      type = enum managerEnumValues;
      default = manager;
      description = "Display manager or greeter used to start graphical sessions.";
    };
    defaultSession = mkOption {
      type = nullOr str;
      default = session;
      description = "Default graphical session selected by the display manager.";
    };
    autoLogin = {
      enable = mkEnableOption "automatic login" // {default = auto.enable;};
      user = mkOption {
        type = nullOr str;
        default = auto.user;
        description = "User to automatically log in when autologin is enabled.";
      };
    };
  };

  dmsCompositors = ["hyprland" "niri" "sway"];

  mk = scope: {config, ...}: let
    mod = mkModuleArgs {inherit config top scope path;};
    cfg = mod.get.config.module;
    opt = mod.set.options.module;
    session = login.defaultSession or (defaultSession host);
    greeter = cfg.manager;
    compositor = let
      pref = primaryBackend host;
    in
      if pref != null && elem pref.name dmsCompositors
      then pref.name
      else null;
  in {
    options = opt (opts (displayManagerFor host) session);

    config =
      if scope == "core"
      then {
        assertions = [
          {
            assertion = (greeter != "dms") || compositor != null;
            message = "DMS greeter requires a supported compositor (hyprland, niri, or sway) from the selected interface backend.";
          }
        ];
        programs.regreet.enable = greeter == "regreet";
        services = {
          displayManager = mkIf (greeter != "none") {
            gdm.enable = greeter == "gdm";
            sddm.enable = greeter == "sddm";
            dms-greeter = mkIf (greeter == "dms") {
              enable = true;
              compositor.name = compositor;
            };
            autoLogin = mkIf cfg.autoLogin.enable {
              enable = true;
              user = cfg.autoLogin.user;
            };
          };
          xserver.displayManager.lightdm.enable = greeter == "lightdm";
          greetd = mkIf (elem greeter ["dms" "greetd" "regreet"]) {enable = true;};
        };
      }
      else {};
  };
in {
  core = mk "core";
  home = mk "home";
}

_flake: {
  config,
  host,
  pkgs,
  top,
  ...
}: let
  inherit
    (builtins)
    attrNames
    concatLists
    filter
    isAttrs
    mapAttrs
    head
    isBool
    isList
    listToAttrs
    pathExists
    readDir
    ;

  hostName = host.name;
  enabledUsers = host.users.byStatus.enabled.values or {};
  enabledUserNames = attrNames enabledUsers;

  normalizeValue = value:
    if isBool value
    then {enable = value;}
    else if isAttrs value
    then ({enable = value.enable or true;} // value)
    else {
      enable = true;
      inherit value;
    };

  normalizeServices = value:
    if isList value
    then
      listToAttrs (map (name: {
          inherit name;
          value = {enable = true;};
        })
        value)
    else if isAttrs value
    then mapAttrs (_: normalizeValue) value
    else {};

  hostServices = normalizeServices (host.services or {});
  aiServices = hostServices.ai or {};
  hermesCfg = aiServices.hermes or {};
  hermesSecretCfg = hermesCfg.envSecret or {};
  tailscaleCfg = hostServices.tailscale or {};
  tailscaleSecretCfg = tailscaleCfg.authKeySecret or {};

  hostSecretFile = let
    hostRoots = filter pathExists [
      ../../../data/hosts
    ];

    dirNames = root:
      filter
      (name:
        ((readDir root).${name} == "directory")
        && pathExists (root + "/${name}/default.nix"))
      (attrNames (readDir root));

    nameMapped = root: dirName: let
      specPath = root + "/${dirName}/default.nix";
      spec = import specPath;
    in
      if (spec.name or dirName) == hostName
      then root + "/${dirName}/secrets.yaml"
      else null;

    discovered = concatLists (
      map
      (root:
        map
        (dirName: nameMapped root dirName)
        (dirNames root))
      hostRoots
    );

    existing = filter (file: file != null && pathExists file) (
      [
        ../../../data/hosts/${hostName}/secrets.yaml
      ]
      ++ discovered
    );
  in
    if existing == []
    then null
    else head existing;

  userSecretFile = userName: ../../../data/users/${userName}/secrets.yaml;

  homeDir = userName: "/home/${userName}";
  sshDir = userName: "${homeDir userName}/.ssh";
  githubDir = userName: "${sshDir userName}/github";

  githubIdentities = userName:
    attrNames (enabledUsers.${userName}.git or {});

  mkAttrs = listToAttrs;

  mkDirRules = userName: let
    identities = githubIdentities userName;
  in
    ["d ${sshDir userName} 0700 ${userName} users - -"]
    ++ (
      if identities == []
      then []
      else ["d ${githubDir userName} 0700 ${userName} users - -"]
    );

  dirRules = concatLists (map mkDirRules enabledUserNames);

  mkHostSecret = name: {
    inherit name;
    value.sopsFile = hostSecretFile;
  };

  hostSecrets =
    if hostSecretFile == null
    then {}
    else
      mkAttrs (
        (
          if hermesSecretCfg.enable or hermesCfg.enable or false
          then [
            (mkHostSecret (hermesSecretCfg.name or "services/ai/hermes/env"))
          ]
          else []
        )
        ++ (
          if tailscaleSecretCfg.enable or false
          then [
            (mkHostSecret (tailscaleSecretCfg.name or "services/tailscale/authKey"))
          ]
          else []
        )
      );

  mkPasswordSecret = userName: {
    name = "users/${userName}/passwordHash";
    value = {
      sopsFile = userSecretFile userName;
      neededForUsers = true;
    };
  };

  mkPrimarySshSecrets = userName: [
    {
      name = "ssh/${userName}/id_ed25519/private";
      value = {
        sopsFile = userSecretFile userName;
        owner = userName;
        path = "${sshDir userName}/id_ed25519";
        mode = "0600";
      };
    }
    {
      name = "ssh/${userName}/id_ed25519/public";
      value = {
        sopsFile = userSecretFile userName;
        owner = userName;
        path = "${sshDir userName}/id_ed25519.pub";
        mode = "0644";
      };
    }
  ];

  mkGithubSecrets = userName:
    concatLists (
      map
      (identity: [
        {
          name = "ssh/${userName}/github/${identity}/private";
          value = {
            sopsFile = userSecretFile userName;
            owner = userName;
            path = "${githubDir userName}/${identity}";
            mode = "0600";
          };
        }
        {
          name = "ssh/${userName}/github/${identity}/public";
          value = {
            sopsFile = userSecretFile userName;
            owner = userName;
            path = "${githubDir userName}/${identity}.pub";
            mode = "0644";
          };
        }
      ])
      (githubIdentities userName)
    );

  userSecrets = mkAttrs (
    concatLists (
      map
      (userName:
        [(mkPasswordSecret userName)]
        ++ mkPrimarySshSecrets userName
        ++ mkGithubSecrets userName)
      enabledUserNames
    )
  );

  passwordAssignments = mkAttrs (
    map (userName: {
      name = userName;
      value.hashedPasswordFile =
        config.sops.secrets."users/${userName}/passwordHash".path;
    })
    enabledUserNames
  );

  hermesSecretName = hermesSecretCfg.name or "services/ai/hermes/env";
  tailscaleSecretName = tailscaleSecretCfg.name or "services/tailscale/authKey";
in {
  environment.systemPackages = with pkgs; [
    age
    ssh-to-age
    ssh-to-pgp
    sops
    gnupg
    openssh
  ];

  systemd.tmpfiles.rules = dirRules;

  sops =
    {
      defaultSopsFormat = "yaml";
      age.sshKeyPaths = ["/etc/ssh/ssh_host_ed25519_key"];
      secrets = hostSecrets // userSecrets;
    }
    // (
      if hostSecretFile == null
      then {}
      else {defaultSopsFile = hostSecretFile;}
    );

  ${top}.services =
    (
      if hostSecretFile != null && (hermesSecretCfg.enable or hermesCfg.enable or false)
      then {
        ai.hermes.envSecret.path = config.sops.secrets.${hermesSecretName}.path;
      }
      else {}
    )
    // (
      if hostSecretFile != null && (tailscaleSecretCfg.enable or false)
      then {
        tailscale.authKeySecret.path = config.sops.secrets.${tailscaleSecretName}.path;
      }
      else {}
    );

  users.users = passwordAssignments;
}

{lix, ...} @ args: let
  inherit (lix.modules) mkModules;
in
  mkModules (
    args
    // {
      base = ./.;
      recurse = true;
      extraArgs = args.extraArgs or {};
    }
  )

{
  lix,
  top,
  shared,
  ...
} @ args: let
  inherit (lix.ingestion) ingest;
  inherit (lix.lists) last;
  inherit (lix.options) mkEnable mkModuleArgs mkOption;
  inherit (lix.types) anything;

  registry = {
    claude = {
      provider = "anthropic";
      requiresContainer = false;
      homeCapable = true;
    };
    codex = {
      provider = "openai";
      requiresContainer = false;
      homeCapable = true;
    };
    ollama = {
      provider = "local";
      requiresContainer = false;
      homeCapable = false;
    };
    openclaw = {
      provider = "openclaw";
      requiresContainer = false;
      homeCapable = true;
    };
    hermes = {
      provider = "openai-codex";
      requiresContainer = true;
      homeCapable = false;
    };
  };

  mkChild = {
    path,
    extraOptions ? (_: {}),
    extraConfig ? (_: {}),
  }: let
    name = last path;
    entry = registry.${name} or {};
    staged = shared.ai.${name} or {};

    defaults = {
      enable = staged.enable or false;
      provider = staged.provider or (entry.provider or null);
    };

    mk = scope: {
      config,
      options ? {},
      pkgs ? {},
      ...
    }: let
      mod = mkModuleArgs {inherit config options top scope path;};
      opt = mod.set.options.module;
      cfg = mod.get.config.module;

      fields = {
        enable = mkEnable {
          inherit name scope;
          default = defaults.enable;
        };
        provider = mkOption {
          type = anything;
          default = defaults.provider;
          description = "AI provider backing ${name}.";
        };
      };
    in {
      options = opt (fields // extraOptions {inherit scope cfg entry staged;});
      config = extraConfig {inherit scope cfg entry staged pkgs;};
    };
  in {
    core = mk "core";
    home = mk "home";
  };

  inner = ingest (args
    // {
      base = ./.;
      declareRegistry = true;
      extraArgs = {inherit shared registry mkChild;};
      excludes = [
        "claude"
        # "codex"
        "ollama"
        "openclaw"
      ];
    });
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  lix,
  top,
  shared,
  ...
}: let
  inherit (lix.options) mkEnable mkModuleArgs mkOption;
  inherit (lix.types) anything attrsOf nullOr str submodule;

  staged = shared.streaming or {};
  stagedIngress = staged.ingress or {};

  mk = scope: {config, ...}: let
    mod = mkModuleArgs {
      inherit config top scope;
      path = ["services"];
    };
    opt = mod.set.options.module;
  in {
    options = opt {
      streaming = mkOption {
        type = submodule {
          freeformType = attrsOf anything;
          options = {
            enable = mkEnable {
              name = "streaming";
              inherit scope;
              default = staged.enable or false;
            };
            provider = mkOption {
              type = nullOr str;
              default = staged.provider or null;
              description = "Primary staged streaming stack/provider name for this host.";
            };
            endpoint = mkOption {
              type = nullOr str;
              default = staged.endpoint or null;
              description = "Primary external endpoint or URL for the staged streaming service.";
            };
            ingress = mkOption {
              type = submodule {
                freeformType = attrsOf anything;
                options = {
                  domain = mkOption {
                    type = nullOr str;
                    default = stagedIngress.domain or null;
                    description = "Canonical domain intended to front the streaming service.";
                  };
                  proxy = mkOption {
                    type = nullOr str;
                    default = stagedIngress.proxy or null;
                    description = "Reverse proxy or ingress implementation expected to expose the streaming stack.";
                  };
                };
              };
              default = stagedIngress;
              description = "Staged ingress metadata for future streaming native wiring.";
            };
          };
        };
        default = staged;
        description = "Staged streaming service configuration under dots.services before native wiring.";
      };
    };

    config = {};
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  host,
  ...
} @ args: let
  inherit (lix.modules) mkModules;
  inherit (lix.attrsets) normalize;

  inner = mkModules (args
    // {
      base = ./.;
      extraArgs.shared = normalize (host.services or {});
    });
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  lix,
  top,
  host,
  path,
  ...
} @ args: let
  inherit (lix.attrsets) attrByPath;
  inherit (lix.ingestion) ingest;
  inherit (lix.lists) elem;
  inherit (lix.options) mkModuleArgs mkOption;
  inherit (lix.types) package;

  here = path;

  registry = {
    git.package = "gitFull";
    lfs.package = "git-lfs";
    gh.package = "gh";
    jj.package = "jujutsu";
    gitui.package = "gitui";
    delta.package = "delta";
  };

  mkArgs = {
    config,
    path,
    pkgs ? {},
    scope ? "core",
    user ? {},
  }: let
    module = mkModuleArgs {inherit config top scope path pkgs;};
    inherit (module) get set;
    inherit (get.names) name;

    domHost = attrByPath here {} host;
    domUser = attrByPath here {} user;
    modHost = attrByPath path {} host;
    modUser = attrByPath path {} user;
    modData = registry.${name} or {};
  in
    module
    // {
      options = {
        enable = set.enable {
          default =
            domUser.enable or (
              domHost.enable or (elem name (
                (host.applications or [])
                ++ (user.applications or [])
              ))
            );
        };
        package = let
          pkg =
            modUser.package or (
              modHost.package or (
                modData.package or name
              )
            );
        in
          mkOption {
            type = package;
            default = pkgs.${pkg} or null;
            description = "Package of '${pkg}' for ${scope}.";
          };
      };
    };

  inner = ingest (args
    // {
      base = ./.;
      declareRegistry = true;
      extraArgs = {inherit registry mkArgs;};
    });
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  zen-twilight = "zen-browser";
}

{
  browsers = ["zen-browser" "chromium"];
  editors = ["helix" "neovim"];
  visuals = ["vscode" "zeditor"];
  terminals = ["foot" "kitty" "alacritty" "warp-terminal" "ghostty"];
  launchers = ["vicinae" "fuzzel"];
  shells = ["bash" "nushell" "powershell"];
  bar = ["noctalia" "quickshell"];
  prompt = ["starship"];
}

{
  alacritty = {
    groups = ["terminals"];
    scopes = ["core" "home"];
  };
  foot = {
    groups = ["terminals"];
    scopes = ["core" "home"];
    protocol = "wayland";
  };
  git = {
    groups = ["development"];
    scopes = ["core" "home"];
  };
  kitty = {
    groups = ["terminals"];
    scopes = ["core" "home"];
  };
  noctalia = {
    groups = ["bar" "frontend"];
    scopes = ["home"];
    protocol = "wayland";
  };
  starship = {
    groups = ["prompt"];
    scopes = ["core" "home"];
  };
  vicinae = {
    groups = ["launchers"];
    scopes = ["home"];
    protocol = "wayland";
  };
  zen-browser = {
    groups = ["browsers"];
    scopes = ["home"];
  };
}

{
  brand = "ACER";
  resolution = "1920x1080";
