      #     "x-systemd.automount"
      #     "x-systemd.idle-timeout=60"
      #   ];
      # };
    };

    swap = [];

    network = [
      "enp9s0"
      "wlp8s0"
    ];

    display = {
      "HDMI-A-3" = {
        brand = "KTC";
        resolution = "2560x1440";
        refreshRate = 100;
        scale = 1;
        # Centered below DP-3: (2560 - 1600) / 2 = 480 → x=480; y=900 (below 900px tall DP-3)
