        # };
      };
      zen-browser = {
        input = "browserZen";
        scopes = ["desktop" "browser"];
        modules.home = ["default"];
      };
    };

    lib = inputs.${inputs'.nixpkgs.input}.lib;
    inherit
      (lib.attrsets)
      attrNames
      attrValues
      filterAttrs
      getAttr
      genAttrs
      hasAttr
      # isAttrs
      # isDerivation
      mapAttrs
      optionalAttrs
      recursiveUpdate
      ;
    inherit (lib.lists) any concatMap elem filter findFirst foldl' optionals unique;
    inherit (lib.strings) concatStringsSep;

    classes = {
      modules = {
        nixos = ["nixosModules"];
        darwin = ["darwinModules"];
        home = ["homeModules" "homeManagerModules" "hmModules"];
      };
      names = attrNames classes.modules;
    };

    registerInputs = name: {
      input,
      scopes,
      modules ? {},
      overlays ? [],
    }: let
      source = inputs.${input} // {name = input;};
    in {
      inherit scopes source;
      overlays = registerOverlays {inherit name source overlays;};
      libraries = registerLibraries source;
      packages = registerPackages source;
      modules = registerModules {inherit name source modules;};
    };

    registerModules = {
      name,
      source,
      modules,
    }: let
      fromClass = class: let
        key = findFirst (k: source ? ${k}) null classes.modules.${class};
      in
        optionalAttrs (key != null) source.${key};

      pickModules = class: set: let
        selected = modules.${class} or [];
        missing = filter (key: !(hasAttr key set)) selected;
      in
        if missing == []
        then map (key: getAttr key set) selected
        else
          throw "flake.registry.modules: ${name}.${class} missing module(s): ${
            concatStringsSep ", " missing
          }";

      modulesOf = class: let
        resolved = fromClass class;
        shouldInclude = resolved != {} && (modules.${class} or []) != [];
      in
        optionals shouldInclude (pickModules class resolved);
    in
      genAttrs classes.names modulesOf;

    registerLibraries = source: let
      set = source.lib or {};
    in
      set // optionalAttrs (set ? hm) set.hm;

    registerOverlays = {
      name,
      source,
      overlays,
    }: let
      set = source.overlays or {};
      missing = filter (key: !(hasAttr key set)) overlays;
      auto = let
        target =
          if set ? ${name}
          then name
          else "default";
      in
        set // {default = set.${target} or null;};
    in
      if overlays == []
      then auto
      else if missing == []
      then genAttrs overlays (key: getAttr key set)
      else throw "flake.registry.overlays: ${name} missing overlay(s): ${concatStringsSep ", " missing}";

    registerPackages = source:
      source.packages or {};

    registry = let
      entries =
        mapAttrs
        (name: spec: (registerInputs name spec))
        inputs';

      matchingScopes = wanted:
        filterAttrs (_: entry: any (scope: elem scope entry.scopes) wanted) entries;

      aggregated = {
        libraries = let
          base = entries.nixpkgs.libraries;
          extra =
            foldl'
            (acc: name: recursiveUpdate acc entries.${name}.libraries)
            {}
            ["nix-darwin"];
          named =
            mapAttrs
            (_: entry: entry.libraries)
            (
              filterAttrs
              (
                _: entry:
                  !elem "infrastructure" entry.scopes
                  && entry.libraries != {}
              )
              entries
            );
        in
          recursiveUpdate (recursiveUpdate base extra) named;

        modules = let
          entryList = attrValues entries;
          byScope = class: scope:
            concatMap
            (
              entry:
                optionals
                (elem scope entry.scopes)
                (entry.modules.${class} or [])
            )
            entryList;
          scopes = unique (concatMap (entry: entry.scopes) entryList);
          forClass = class:
            {
              all = concatMap (entry: entry.modules.${class} or []) entryList;
              select = wanted:
                concatMap
                (entry: entry.modules.${class} or [])
                (attrValues (matchingScopes wanted));
            }
            // genAttrs scopes (byScope class);
        in
          genAttrs classes.names forClass;

        overlays = let
          entryList = attrValues entries;
          values = entry: filter (v: v != null) (attrValues entry.overlays);
          byScope = scope:
            concatMap
            (entry: optionals (elem scope entry.scopes) (values entry))
            entryList;
          scopes = unique (concatMap (entry: entry.scopes) entryList);
        in
          {
            all = concatMap values entryList;
            select = wanted: (concatMap values (attrValues (matchingScopes wanted)));
          }
          // genAttrs scopes (scope: (byScope scope));

        packages = let
          validEntries = filterAttrs (_: entry: entry.packages != {}) entries;
          allSystems = unique (
            concatMap
            (entry: attrNames entry.packages)
            (attrValues validEntries)
          );
        in
          genAttrs allSystems (
            system: let
              nixpkgs = import flake.registry.nixpkgs.source.outPath {
                inherit system;
                config = {inherit (defaults) allowUnfree;};
              };
            in
              foldl' (
                acc: name: let
                  pkgSet = entries.${name}.packages.${system} or {};
                in
                  acc
                  // (
                    filterAttrs
                    (key: _: !(hasAttr key nixpkgs))
                    (removeAttrs pkgSet [
                      "debug"
                      "default"
                      "full"
                      "minimal"
                      "rust"
                    ])
                  )
                  // (
                    optionalAttrs
                    (pkgSet ? default)
                    {${name} = pkgSet.default;}
                  )
              ) {} (attrNames validEntries)
          );
      };
    in
      entries // {inherit aggregated;};

    defaults = {
      allowUnfree = true;
      pkgAliases = {
        caelestia = "caelestia-shell";
        dank-material = "dms-shell";
        niri = "niri-unstable";
        openclaw = ["llm-agents" "openclaw"];

        # FIX: We shouldn't need to do this
        # "noctalia-shell" = "noctalia";
        # "dms" = "dms-shell";
      };
    };
    flake = {inherit defaults registry;};
    src = import ./. {inherit flake;};
    base = src.${src.names.src};
    libs = src.${src.names.lib};
    inherit (libs.assembly) mkFlake';
  in
    {
      lib = base;
      inherit flake;
    }
    // mkFlake' base {
      configuration = true;
      utilities = true;
      shells = true;
      templates = true;
    }
    // {};
}

{
  api,
  attrsets,
  lists,
  ...
}: let
  exports = {
    scoped = {
      inherit
        aliases
        categories
        namesOf
        registry
        selectedModules
        selectionOf
        ;
    };

    global = {
      applicationRegistry = registry;
      applicationCategories = categories;
      applicationAliases = aliases;
      applicationSelection = selectionOf;
      applicationNames = namesOf;
      applicationModules = selectedModules;
    };
  };

  inherit (attrsets) valuesOf filterAttrs;
  inherit (lists) concatMap elem unique;

  registry = removeAttrs (api.applications.modules or {}) ["name" "tags"];
  categories = removeAttrs (api.applications.categories or {}) ["name" "tags"];
  aliases = removeAttrs (api.applications.aliases or {}) ["name" "tags"];

  selectionOf = spec: spec.applications or {};
  normalizeName = name: aliases.${name} or name;

  namesOf = spec:
    unique (
      map
      normalizeName
      (concatMap valuesOf (valuesOf (selectionOf spec)))
    );

  selectedModules = spec: let
    names = namesOf spec;
  in
    filterAttrs (name: _: elem name names) registry;
in
  exports

{
  args,
  attrsets,
  filesystem,
  ingestion,
  paths,
  types,
  ...
}: let
  inherit (attrsets) listToAttrs mapAttrs recursiveUpdate;
  inherit (filesystem) mkPaths';
  inherit (ingestion) collectNamedSpecs;
  inherit (types) isList;

  domains = {
    hosts.includeFiles = false;
    users.includeFiles = false;
    displays.includeFiles = true;
    interface.includeFiles = true;
    applications.includeFiles = true;
  };

  specs = let
    base = paths.store.api or paths.store.data or {};
    src = base.src or ../../data;
    derived =
      mapAttrs
      (name: _: base.${name} or (src + "/${name}"))
      domains;
    resolved =
      recursiveUpdate paths
      {store.api = derived // {inherit src;};};
  in
    (mkPaths' {inherit (resolved) store local;}).store.api;

  extra = {
    normalize = raw:
      if isList raw
      then
        listToAttrs (map (name: {
            inherit name;
            value = {};
          })
          raw)
      else raw;
  };
in
  mapAttrs (name: domain:
    collectNamedSpecs {
      inherit (domain) includeFiles;
      args = args // extra;
      base = specs.${name};
      rekey = true;
    })
  domains

{
  attrsets,
  lists,
  strings,
  api,
  ...
}: let
  exports = {
    scoped = {inherit registry resolve;};
    global = {
      displayRegistry = registry;
      resolveDisplays = resolve;
    };
  };

  inherit (attrsets) listToAttrs mapAttrs mapAttrsToList;
  inherit (lists) elemAt foldl' length imap0 isList sort;
  inherit (strings) isString splitString toInt;

  registry = api.displays;

  resolve = host: let
    hostPath = "api/hosts/${host.name}";
    fail = msg: throw "${hostPath}: ${msg}";
    raw = (host.devices or {}).display or [];

    cleanDisplay = display:
      removeAttrs display [
        "display"
        "monitor"
        "name"
        "output"
        "tags"
      ];

    parseSize = resolution: let
      parts = splitString "x" resolution;
    in {
      width = toInt (elemAt parts 0);
      height = toInt (elemAt parts 1);
    };

    parsePoint = position: let
      parts = splitString "x" position;
    in {
      x = toInt (elemAt parts 0);
      y = toInt (elemAt parts 1);
    };

    isPoint = position:
      isString position && length (splitString "x" position) == 2;

    resolveDisplay = idx: cfg: let
      output =
        cfg.output
        or (fail "display at index ${toString idx} missing 'output'");

      display =
        if cfg ? display || cfg ? monitor
        then let
          name =
            cfg.display
            or (cfg.monitor or (
              fail "display '${output}' missing 'display'"
            ));
        in
          registry.${name}
          or (fail "display '${output}' references unknown display '${name}'")
        else cfg;

      merged =
        cleanDisplay display
        // {
          enable = cfg.enable or true;
          priority = cfg.priority or idx;
          primary = cfg.primary or (idx == 0);
          position = cfg.position or "right";
        }
        // (removeAttrs cfg ["display" "monitor" "output"]);

      size =
        if (merged.resolution or null) != null
        then parseSize merged.resolution
        else {
          width = 0;
          height = 0;
        };
    in {
      name = output;
      value =
        merged
        // {
          layout = {
            inherit size;
            position = {
              x = 0;
              y = 0;
            };
          };
        };
    };

    resolved =
      if isList raw
      then listToAttrs (imap0 resolveDisplay raw)
      else
        mapAttrs
        (output: cfg:
          (resolveDisplay 0 (cfg // {inherit output;})).value)
        raw;

    ordered =
      sort
      (a: b: a.value.priority < b.value.priority)
      (mapAttrsToList (name: value: {inherit name value;}) resolved);

    leftWidth =
      foldl'
      (total: item:
        if item.value.position == "left"
        then total + item.value.layout.size.width
        else total)
      0
      ordered;

    topHeight =
      foldl'
      (total: item:
        if item.value.position == "top"
        then total + item.value.layout.size.height
        else total)
      0
      ordered;

    place = item: let
      display = item.value;
      inherit (display) position;

      point =
        if position == null
        then {
          x = 0;
          y = 0;
        }
        else if isPoint position
        then parsePoint position
        else if position == "left"
        then {
          x = 0;
          y = topHeight;
        }
        else if position == "right"
        then {
          x = leftWidth;
          y = topHeight;
        }
        else if position == "top"
        then {
          x = 0;
          y = 0;
        }
        else if position == "bottom"
        then {
          x = 0;
          y = topHeight;
        }
        else if position == "center"
        then {
          x = leftWidth;
          y = topHeight;
        }
        else fail "display '${item.name}' has invalid position '${position}'";
    in {
      inherit (item) name;
      value =
        display
        // {layout = (display.layout or {}) // {position = point;};};
    };
  in
    listToAttrs (map place ordered);
in
  exports

{
  defaults,
  attrsets,
  lists,
  users,
  displays,
  api,
  ...
}: let
  exports = {
    scoped = {
      inherit registry getScopes normalize;
      inherit (registry) default;
    };

    global = {
      hostRegistry = registry;
      getHostScopes = getScopes;
      normalizeHost = normalize;
    };
  };
  inherit (attrsets) attrNames mapAttrs;
  inherit (lists) asListIf elem head unique;

  normalize = host: let
    arch = host.arch or "x86_64";
    os = host.os or "linux";
    class = host.class or "nixos";
    system = host.system or "${arch}-${os}";
  in
    host // {inherit arch os class system;};

  registry = let
    specs =
      mapAttrs
      (_: host:
        normalize (
          host
          // {
            users = users.resolveUsers host;
            devices = (host.devices or {}) // {display = displays.resolveDisplays host;};
          }
        ))
      api.hosts;

    known = specs;
    fallback = known.${defaults.host} or known.${head (attrNames known)};
  in
    known // {default = normalize fallback;};

  getScopes = host: let
    type = host.type or "desktop";
    isDesktop = type == "laptop" || type == "desktop";

    iface = host.interface or {};
    wm = iface.windowManager or null;
    de = iface.desktopEnvironment or null;
    hasUI = isDesktop && (wm != null || de != null);

    funcs = host.functionalities or [];
  in
    unique (
      [
        "core"
        "infrastructure"
        "secrets"
        "deployment"
      ]
      ++ (
        asListIf isDesktop [
          "ai"
          "browser"
          "code"
          "desktop"
          "development"
          "editor"
          "formatter"
          "language"
          "launcher"
          "theming"
          "ui"
        ]
      )
      ++ (asListIf hasUI ["window-manager" "shell"])
      ++ (asListIf (elem "storage" funcs) "storage")
    );
in
  exports

{
  api,
  attrsets,
  lists,
  paths,
  ...
}: let
  exports = {
    scoped = {inherit registry inferredOf selectionOf selectedModules backendsOf;};
    global = {
      interfaceRegistry = registry;
      interfaceSelection = selectionOf;
      interfaceInferred = inferredOf;
      interfaceBackends = backendsOf;
      interfaceModules = selectedModules;
    };
  };

  inherit (attrsets) as filterAttrs valuesOf mapAttrs recursiveUpdate;
  inherit (lists) concatMap elem filter unique;

  raw = api.interface;

  # data/interface/default.nix -- common/wayland/x11-shaped defaults.
  # wayland/x11 already have common's applications concatenated in (via ++
  # at the data layer). resolveProtocol still merges common underneath,
  # since only common declares bindings/variables and those must fall
  # through even for the categories wayland/x11 don't redeclare.
  # default.nix is never picked up as a sibling registry entry
  # (readDirAttrs excludes it), so it must be imported directly.
  shared = import (paths.store.api + "/interface");
  common = shared.common or {};
  resolveProtocol = protocol: recursiveUpdate common (shared.${protocol} or {});

  # protocol (lowest) -> entry (highest), with applications.<category>
  # concatenated rather than replaced: an entry's own list becomes the new
  # primary/prepended entries, and whatever the protocol tier already had
  # (which itself already has common concatenated in via ++) falls back
  # after it. Every other key (bindings, variables, protocol, greeter, ...)
  # keeps plain override-wins semantics.
  mergeLayer = entry: let
    protocol = resolveProtocol (entry.protocol or "common");
    entryApps = entry.applications or {};
    protocolApps = protocol.applications or {};
    mergedApps =
      protocolApps
      // mapAttrs
      (category: list: list ++ (protocolApps.${category} or []))
      entryApps;
  in
    (recursiveUpdate protocol entry) // {applications = mergedApps;};

  registry =
    mapAttrs
    (_: entry: mergeLayer entry)
    (removeAttrs raw ["default"]);

  rawBackendsOf = spec: let
    interface = spec.interface or {};
  in
    interface.backends
    or (
      unique (
        filter (x: x != null && x != "") (
          (interface.backend.managers or [])
          ++ (interface.backend.desktops or [])
          ++ [
            (interface.windowManager or null)
            (interface.desktopEnvironment or null)
          ]
        )
      )
    );

  selectionOf = spec: spec.applications or {};
  inferredOf = spec: as (rawBackendsOf spec);
  normalizeName = name: registry.${name} or name;

  backendsOf = spec:
    unique (
      map
      normalizeName
      (concatMap valuesOf (valuesOf (selectionOf spec)))
    );

  selectedModules = spec: let
    names = backendsOf spec;
  in
    filterAttrs (name: _: elem name names) registry;
in
  exports

{
  attrsets,
  lists,
  api,
  ...
}: let
  exports = let
    scoped = {
      inherit
        registry
        getUsers
        getEnabledUsers
        getAdminUsers
        getNormalUsers
        getInteractiveUsers
        resolveUsers
        ;
    };
  in {
    inherit scoped;
    global =
      scoped
      // {
        userRegistry = scoped.registry;
        admins = scoped.getAdminUsers;
        enabledUsers = scoped.getEnabledUsers;
        loginUsers = scoped.getInteractiveUsers;
        normalUsers = scoped.getNormalUsers;
      };
  };

  inherit (attrsets) attrNames filterAttrs genAttrs listToAttrs mapAttrs;
  inherit (lists) elemAt filter imap0 isList length;

  registry = api.users;

  getUsers = spec: let
    mkGroup = attrs: let
      names = attrNames attrs;
      values =
        mapAttrs
        (name: user:
          user
          // {
            inherit name;
            description = user.description or name;
          })
        attrs;
      count = length names;
    in {inherit names values count;};

    filterByStatus = status: attrs:
      filterAttrs
      (_: user: (user.enable or true) == (status == "enabled"))
      attrs;

    filterByRole = wantedRole: attrs:
      filterAttrs
      (_: user: let
        role = user.role or "";
        isNormal = role == "" || role == "user" || role == "normal";
      in
        if wantedRole == "normal"
        then isNormal
        else role == wantedRole)
      attrs;

    mkRoleIndex = attrs:
      genAttrs ["normal" "administrator" "service" "guest"] (role:
        mkGroup (filterByRole role attrs));

    mkStatusIndex = attrs:
      genAttrs ["enabled" "disabled"] (status: let
        subset = filterByStatus status attrs;
      in
        (mkGroup subset) // {byRole = mkRoleIndex subset;});

    users =
      mapAttrs
      (_: user:
        {
          role = "user";
          enable = true;
        }
        // user)
      spec;
  in
    (mkGroup users) // {byStatus = mkStatusIndex users;};

  usersOf = host:
    if host ? users.values
    then host.users
    else getUsers host.users; # TODO: This should not be failing as every host much define users

  getEnabledUsers = host:
    (usersOf host).byStatus.enabled.values;

  getAdminUsers = host:
    (usersOf host).byStatus.enabled.byRole.administrator.values;

  getNormalUsers = host:
    (usersOf host).byStatus.enabled.byRole.normal.values;

  getInteractiveUsers = host: let
    users = (usersOf host).byStatus.enabled.byRole;
  in
    users.administrator.values
    // users.normal.values
    // users.guest.values;

  resolveUsers = host: let
    hostPath = "api/hosts/${host.name}";
    fail = msg: throw "${hostPath}: ${msg}";

    hostUsers = host.users or {};

    declared =
      if isList hostUsers
      then
        listToAttrs (
          imap0
          (idx: user: {
            name =
              user.name or (
                fail "user at index ${toString idx} missing 'name'"
              );
            value =
              removeAttrs user ["name"]
              // {primary = user.primary or (idx == 0);};
          })
          hostUsers
        )
      else hostUsers;

    isSingleUser = length (attrNames declared) == 1;

    resolveUser = userName: config: let
      spec =
        registry.${userName}
        or (fail "user '${userName}' not found in api/users");

      defaults = {
        role =
          if isSingleUser
          then config.role or "administrator"
          else "user";

        enable =
          if isSingleUser
          then config.enable or true
          else true;

        primary =
          if isSingleUser
          then config.primary or true
          else false;

        autoLogin = false;
      };
    in
      spec // defaults // config;

    resolved = getUsers (mapAttrs resolveUser declared);

    primary = let
      enabled = resolved.byStatus.enabled;
      candidates =
        filter
        (n: enabled.values.${n}.primary or false)
        enabled.names;

      name =
        if enabled.count == 0
        then null
        else if length candidates == 0 && enabled.count == 1
        then elemAt enabled.names 0
        else if length candidates == 0
        then fail "expected exactly one primary enabled user, found none"
        else if length candidates > 1
        then fail "expected exactly one primary enabled user, found ${toString (length candidates)}"
        else elemAt candidates 0;
    in {
      inherit name;
      value =
        if name == null
        then null
        else enabled.values.${name};
    };
  in
    resolved // {inherit primary;};
in
  exports

{
  attrsets ? {},
  trivial ? {},
  filesystem ? {},
  names ? {},
  ...
}: let
  exports = {
    scoped = {
      mkLibs = mkLibrary;
      mkLix = mkLibraryFlat;
      inherit mkLibraryFlat;
    };
    global = {inherit mkLibrary mkLibraryFlat;};
  };

  bootstrap = import ./.;

  inherit (builtins) attrValues foldl' mapAttrs;

  optionalAttrs = attrsets.optionalAttrs or bootstrap.optionalAttrs;
  recursiveUpdate = attrsets.recursiveUpdate or bootstrap.recursiveUpdate;
  recursiveSelf = trivial.recursiveSelf or bootstrap.recursiveSelf;
  getSpecs = filesystem.getSpecs or bootstrap.getSpecs;

  mkLibraryFlat = library:
    recursiveUpdate
    library
    {${names.lib or "lix"} = library.charged;};

  mkLibrary = {
    base,
    excludes ? seed.excludes.paths or ["default"], #TODO: This needs to see folders to skip as will, not just files and if the extension (nix) is present it doesn't skip?
    seed ? {},
    extra ? {},
    args ? null,
  }: let
    clean = set:
      removeAttrs set [
        "flat"
        "global"
        "scoped"
        "value"
        "raw"
      ];

    normalize = spec: let
      global = spec.global or {};
      scoped =
        spec.scoped or (
          if spec ? global
          then {}
          else spec
        );
      value = recursiveUpdate global scoped;
      raw = spec;
    in {inherit global scoped raw value;};

    modules = recursiveSelf (self: let
      scope =
        (optionalAttrs (args != null) {inherit args;})
        // (
          recursiveUpdate
          seed
          (clean (mapAttrs (_: lib: lib.value) self))
        );
    in
      foldl'
      recursiveUpdate
      {}
      (
        map
        (spec: {${spec.name} = normalize (import spec.input scope);})
        (getSpecs {inherit base excludes;})
      ));

    domains = mapAttrs (_: mod: mod.value) modules;
    aliases =
      foldl'
      (acc: mod: recursiveUpdate acc mod.global)
      {}
      (attrValues modules);
    merged = recursiveUpdate domains aliases;
    charged = recursiveUpdate (recursiveUpdate seed extra) merged;
  in {
    inherit aliases charged domains;
    ${names.lib or "lix"} = charged;
    lib = charged.lib or merged;
    excluded = excludes;
  };
in
  exports

{
  strings,
  lists,
  ...
}: let
  exports = {
    scoped = {
      inherit
        as
        asEnabled
        asIf
        firstOf
        gets
        gets'
        inspect
        merge
        normalizePaths
        orEmpty
        orEmpty'
        removePath
        removePaths
        preferDefaultValues
        preferDefault
        select
        valuesOf
        namesOf
        coalesce
        ;
      optionalAttrs = asIf;
      defaultOrAll = preferDefault;
      defaultOrAllValues = preferDefaultValues;
      filter = select;
      fromList = listToAttrs;
      get = getAttr;
      getFirst = firstOf;
      has = hasAttr;
      head = firstOf;
      intersect = intersectAttrs;
      is = isAttrs;
      maps = mapAttrs;
      orEmptyNamed = orEmpty';
    };

    global = {
      inherit
        (builtins)
        attrNames
        attrValues
        getAttr
        hasAttr
        listToAttrs
        isAttrs
        intersectAttrs
        mapAttrs
        zipAttrsWith
        ;
      coalesceAttrs = coalesce;
      defaultOrAllAttrs = preferDefault;
      defaultOrAllValues = preferDefaultValues;
      asAttrs = as;
      asAttrsEnabled = asEnabled;
      asAttrsIf = asIf;
      filterAttrs = select;
      findFirstAttr = firstOf;
      getAttrs = gets;
      getAttrsSafe = gets;
      inheritAttr = orEmpty';
      inspectAttrs = inspect;
      orEmptyAttrs = orEmpty;
      recursiveUpdate = merge;
      recursiveAttrs = merge;
      removeAttrPaths = removePaths;
      removeAttrPath = removePath;
    };
  };

  inherit
    (builtins)
    attrNames
    attrValues
    concatMap
    filter
    foldl'
    getAttr
    hasAttr
    head
    isAttrs
    isFunction
    intersectAttrs
    isList
    isString
    listToAttrs
    mapAttrs
    tail
    typeOf
    ;

  inherit (strings) concat split;
  inherit (lists) unique;

  /**
  Normalize raw path inputs into consistent lists of split string segments.
  Accepts flat strings, lists of segments, or a matrix set containing `scopes` and `items`.

  Options for matrix sets:
    - root:  boolean (default: true). Unconditionally checks the root scope.
    - exact: boolean (default: false). If true, disables full permutation generation
             and treats the provided `scopes` as literal, exact paths.

  Example:
    normalizePaths [ { scopes = ["lib.lists"]; items = ["fold"]; exact = true; } ]
    # => [ ["fold"] ["lib" "lists" "fold"] ]
  */
  normalizePaths = args:
    concatMap (
      entry:
        if isAttrs entry && entry ? scopes && entry ? items
        then let
          permutations = list:
            if list == []
            then [[]]
            else
              concatMap (
                element:
                  map (
                    perm: [element] ++ perm
                  ) (permutations (filter (candidate: candidate != element) list))
              )
              list;

          prefixes = list:
            if list == []
            then []
            else
              [[(head list)]]
              ++ map (perm: [(head list)] ++ perm) (prefixes (tail list));

          scopeStrings =
            (
              if (entry.root or true)
              then [""]
              else []
            )
            ++ (
              if (entry.exact or false)
              then entry.scopes
              else
                map
                (concat ".")
                (concatMap prefixes (permutations entry.scopes))
            );
        in
          concatMap (
            scope:
              map (
                item:
                  split "." (
                    if scope == ""
                    then item
                    else "${scope}.${item}"
                  )
              )
              entry.items
          )
          scopeStrings
        else if isList entry
        then entry
        else [(split "." entry)]
    ) (
      if isAttrs args && args ? paths
      then args.paths
      else args
    );

  /**
  Recursively traverses an attribute set to remove a single pre-segmented path.
  Matches the native `removeAttrs` input style: (set -> path).

  Example:
    removePath { lib = { lists = { fold = ...; }; }; } [ "lib" "lists" "fold" ]
  */
  removePath = set: list:
    if !isAttrs set || list == []
    then set
    else let
      path = {
        initial = head list;
        remaining = tail list;
      };
    in
      if path.remaining == []
      then removeAttrs set [path.initial]
      else if set ? ${path.initial}
      then set // {${path.initial} = removePath set.${path.initial} path.remaining;}
      else set;

  /**
  Remove nested attributes from a set using a list of dot-separated path strings
  or lists of strings. Safe against missing intermediate keys.

  Example (AttrSet style):
    removePaths { inherit set; paths = [ "lists.fold" ]; }

  Example (Positional style - matches removeAttrs):
    removePaths set [ "lists.fold" ]
  */
  removePaths = args: let
    exec = set: list: foldl' removePath set (normalizePaths list);
  in
    if isAttrs args && args ? set && args ? paths
    then with args; exec set paths
    else exec args;

  /**
  Coerce a value into an attrset.

  - Attrsets are returned unchanged
  - Strings become `{ ${value} = {}; }`
  - Lists become an attrset of empty sets keyed by list entries
  - Null becomes an empty attrset `{}`

  # Type
  ```nix
  attrsets.as :: { ... } | String | [ String ] | Null -> { ... }

  # Dependencies
  None

  # Arguments
  value
  : The value to coerce.

  # Examples
  > attrsets.as { a = 1; }
  => { a = 1; }

  > attrsets.as "debug"
  => { debug = {}; }

  > attrsets.as [ "debug" "types" ]
  => { debug = {}; types = {}; }

  > attrsets.as null
  => {}
  */
  as = value: let
    _name = "attrsets.as";
  in
    if isAttrs value
    then value
    else if isString value
    then {${value} = {};}
    else if isList value
    then
      listToAttrs (map (name: {
          inherit name;
          value = {};
        })
        value)
    else if value == null
    then {}
    else throw "${_name}: Unsupported type: ${typeOf value}";

  /**
  Coerce a value into an attrset.

  - Attrsets are returned unchanged
  - Strings become `{ ${value} = true; }`
  - Lists become an attrset of boolean flags keyed by list entries

  # Type
  ```nix
  attrsets.asEnabled :: { ... } | String | [ String ] -> { ... }
  ```

  # Dependencies
  None

  # Arguments
  value
  : The value to coerce.

  # Examples
  > attrsets.asEnabled { a = 1; }
  => { a = 1; }

  > attrsets.asEnabled "debug"
  => { debug = true; }

  > attrsets.asEnabled [ "debug" "types" ]
  => { debug = true; types = true; }
  */
  asEnabled = value: mapAttrs (_name: _v: true) (as value);

  /**
  Conditionally coerce a value into an attrset.

  Returns `as value` when `predicate` is true, otherwise `{}`.

  # Type

  ```nix
  asIf :: Bool -> ({ ... } | String | [ String ]) -> { ... }
  ```

  # Dependencies

  - attrsets.as

  # Arguments

  predicate
  : Whether coercion should happen.

  value
  : The value to coerce when enabled.

  # Examples

  ```nix
  asIf true "flake"
  # => { flake = true; }

  asIf false "flake"
  # => {}
  ```
  */
  asIf = predicate: value:
    if predicate
    then as value
    else {};

  /**
  Filter an attrset by attribute name and value.

  Returns a new attrset containing only the attributes for which
  `predicate name value` returns true.

  # Type

  ```nix
  select :: (String -> a -> Bool) -> { ${String} :: a; } -> { ${String} :: a; }
  ```

  # Dependencies

  None

  # Arguments

  predicate
  : A function taking an attribute name and value.

  set
  : The attrset to filter.

  # Examples

  ```nix
  select (_: value: value != null) { a = 1; b = null; }
  # => { a = 1; }

  select (name: _: name == "a") { a = 1; b = 2; }
  # => { a = 1; }
  ```
  */
  select = predicate: set:
    listToAttrs (
      map
      (name: {
        inherit name;
        value = set.${name};
      })
      (
        filter
        (name: predicate name set.${name})
        (attrNames set)
      )
    );

  /**
  Select a specific list of attributes from an attrset.

  Returns a new attrset containing only the keys specified in the names list.
  Note that this function will throw an evaluation error if any of the specified
  names do not exist in the source attrset.

  # Type
  ```nix
  gets :: [String] -> { ${String} :: a; } -> { ${String} :: a; }
  ```
  # Dependencies
  None

  # Arguments
  names
  : A list of attribute names (strings) to extract.

  attrs
  : The source attrset to extract values from.

  #Examples
  ```nix
  gets [ "a" "c" ] { a = 1; b = 2; c = 3; }
  # => { a = 1; c = 3; }

  gets [ "x" ] { a = 1; }
  # => error: attribute 'x' missing
  ```
  */
  gets = names: attrs:
    listToAttrs (
      map (name: {
        inherit name;
        value = attrs.${name} or {};
      })
      names
    );

  /**
  Safely select a specific list of attributes from an attrset.

  Returns a new attrset containing only the keys specified in the names list
  that actually exist in the source attrset. Missing keys are gracefully ignored.

  # Type
  ```nix
  gets' :: [String] -> { ${String} :: a; } -> { ${String} :: a; }
  ```

  # Dependencies
  None

  # Arguments
  names
  : A list of attribute names (strings) to look for.

  attrs
  : The source attrset to filter against.

  # Examples
  ```nix
  gets' [ "a" "x" ] { a = 1; b = 2; }
  # => { a = 1; }
  ```
  */
  gets' = names: attrs:
    intersectAttrs
    (listToAttrs (map (name: {
        inherit name;
        value = null;
      })
      names))
    attrs;

  /**
  Recursively inspect an attrset or list to a bounded depth.

  Functions and paths are rendered as placeholders to keep inspection safe
  and REPL-friendly.

  # Type

  ```nix
  inspect :: Int -> a -> a
  ```

  # Dependencies

  - debug.inspect

  # Arguments

  level
  : Maximum inspection depth.

  value
  : The value to inspect.

  # Examples

  ```nix
  inspect 1 { a.b = 1; }
  # => { a = "..."; }
  ```
  */
  inspect = level: let
    fn = depth: value: let
      type = typeOf value;
    in
      if depth <= 0
      then "..."
      else if isFunction value
      then "<function>"
      else if isList value
      then map (fn (depth - 1)) value
      else if isAttrs value
      then mapAttrs (_: fn (depth - 1)) value
      else if type == "path"
      then "<path>"
      else value;
  in
    fn level;

  /**
  Recursively merge two attrsets.

  When both sides contain an attrset at the same key, they are merged
  recursively. Otherwise the right-hand value wins.

  # Type

  ```nix
  merge :: AttrSet -> AttrSet -> AttrSet
  ```

  # Dependencies

  - attrsets.merge

  # Arguments

  lhs
  : The base attrset.

  rhs
  : The overriding attrset.

  # Examples

  ```nix
  merge { a.b = 1; } { a.c = 2; }
  # => { a = { b = 1; c = 2; }; }
  ```
  */
  merge = lhs: rhs:
    if isAttrs lhs && isAttrs rhs
    then
      listToAttrs (map
        (name: {
          inherit name;
          value =
            if lhs ? ${name} && rhs ? ${name}
            then merge lhs.${name} rhs.${name}
            else rhs.${name} or lhs.${name};
        })
        (unique (attrNames lhs ++ attrNames rhs)))
    else rhs;

  /**
  Normalize a value to a non-empty attrset.

  Returns the attrset unchanged when `value` is a non-empty attrset.
  Returns `{}` for empty attrsets and non-attrset values.

  # Type

  ```nix
  orEmpty :: a -> { ... }
  ```

  # Dependencies

  - types.isNotEmpty

  # Arguments

  value
  : The value to normalize.

  # Examples

  ```nix
  orEmpty { a = 1; }
