        // {src = resolution.value;};
      meta =
        optionalAttrs
        (resolution.usedKey != null)
        {inherit (resolution) usedKey;};
    };

    flake' = recursiveUpdate flake {
      name =
        flake.name or (
          flake.names.src or (
            names.src or "dots"
          )
        );
      path = flake.path or flake.paths.src or paths'.store.src or null;
    };

    defaults' =
      libraries'.charged.defaults or (
        recursiveUpdate
        defaults
        (flake'.defaults or {})
      );

    excludes' =
      libraries'.charged.excludes or (
        recursiveUpdate
        excludes
        (flake'.excludes or {})
      );

    libraries' = let
      raw =
        checked.extraArgs.libraries or (
          if libraries != null
          then libraries
          else staged
        );
      name = raw.name or names.lib or "lix";
      custom = raw.${name} or raw.merged or raw;
      lib = raw.lib or custom;
    in {
      libraries =
        raw
        // {
          inherit lib name;
          "${name}" = custom;
        };
      "${name}" = custom;
    };

    names' = recursiveUpdate names {
      src = flake'.name;
      lib = libraries'.libraries.name;
    };

    updated = let
      base = {
        names = names';
        paths = paths';
        defaults = defaults';
        excludes = excludes';
      };
    in
      genAttrs
      (attrNames base)
      (name: recursiveUpdate base.${name} (extraArgs.${name} or {}));

    args =
      updated
      // {
        inherit host;
        name = updated.names.src;
      }
      // libraries'
      // (
        optionalAttrs
        (flake.enable or false)
        {flake = flake';}
      );
  in
    args // {${args.names.src} = args;};

  /**
  Flatten structured attribute paths downwards into a standard uppercase
  POSIX shell environment variable map.

  # Type
  ```nix
  mkVariables :: { prefix :: String?, attrs :: AttrSet } -> AttrSet
  ```

  # Dependencies
  ```nix
  - debug.expect
  - attrsets.foldlAttrs
  - strings.toUpper
  ```

  # Arguments
  prefix
  : String token block to pre-append to key configurations.

  attrs
  : The structured dataset map targeted for environment emission.
  */
  mkVariables = arg: let
    _name = "config.environment.mkVariables";
    checked = expect {
      name = _name;
      type = "attrs";
      value = arg;
      context = "flattening attribute architecture maps into shell constants";
    };

    prefix = checked.prefix or null;
    attrs = checked.attrs or {};
  in
    foldlAttrs (
      acc: name: value: let
        # The hybrid curried pattern removes the entire conditional block!
        key = toUpper (concat "_" [prefix name]);
      in
        if isAttrs value && value ? base
        then
          acc
          // {"${key}" = value.base;}
          // mkVariables {
            prefix = key;
            attrs = value;
          }
        else if isString value
        then acc // {"${key}" = value;}
        else acc
    ) {}
    attrs;

  /**
  Generate shell directory jumping aliases based on existing framework path maps.

  # Type
  ```nix
  mkCdAliases :: AttrSet -> AttrSet
  ```

  # Dependencies
  ```nix
  - debug.expect
  - attrsets.foldlAttrs
  ```

  # Arguments
  attrs
  : Base directory mapping layouts providing a path schema.
  */
  mkCdAliases = attrs: let
    _name = "config.environment.mkCdAliases";
    _attrs = expect {
      name = _name;
      type = "attrs";
      value = attrs;
      context = "generating filesystem path alias macros";
    };
  in
    foldlAttrs (
      acc: name: value:
        if isAttrs value && value ? base
        then acc // {"cd_${name}" = "cd ${value.base}";}
        else if isString value
        then acc // {"cd_${name}" = "cd ${value}";}
        else acc
    ) {}
    _attrs;
in
  exports

{
  api,
  assembly,
  defaults,
  attrsets,
  ingestion,
  lists,
  modules,
  options,
  strings,
  types,
  ...
}: let
  exports = {
    scoped = {
      inherit mkModules mkModuleArgs mkCfg mkCfgIf mkOpt mkIf';
      ingest = mkModules;
      configure = mkModuleArgs;
    };
    global = {inherit mkModules mkModuleArgs mkCfgIf mkIf';};
  };

  inherit
    (attrsets)
    asAttrs
    foldMerge
    genAttrs
    hasAttr
    namesOf
    mapAttrs
    mkNamespaced
    optionalAttrs
    recursiveUpdate
    setAttrByPath
    valuesOf
    attrByPath
    isNotEmptyAttr
    ;
  inherit (ingestion) collectSpecs;
  inherit (lists) asList asListIf elem head init last optionals;
  inherit (types) attrs;
  inherit (assembly) mkBindings mkRegistryVariables;
  inherit (modules) mkIf mkMerge;
  inherit (options) mkEnable mkOption;
  inherit (strings) concatStringsSep toSentenceCase;
  inherit (types) isList;

  mkModules = args @ {
    base,
    data ? (
      let
        domain =
          if path != []
          then (last path)
          else null;
      in
        args.extraArgs.registry or (
          optionalAttrs
          (domain != null && api ? ${domain}.registry)
          api.${domain}.registry
        )
    ),
    excludes ? null,
    extraArgs ? {},
    includeFiles ? true,
    includes ? [],
    path ? [],
    childPath ? path,
    recurse ? true,
    tags ? defaults.tags,
    top,
    declareRegistry ? isNotEmptyAttr data,
    ...
  }: let
    hasData = isNotEmptyAttr data && declareRegistry;

    specs = collectSpecs {
      inherit args base excludes includes tags includeFiles recurse;
      path = childPath;
      extraArgs =
        recursiveUpdate (args.extraArgs or {}) extraArgs
        // optionalAttrs hasData {registry = data;};
    };

    registryModule = {
      options = setAttrByPath ([top] ++ path ++ ["registry"]) (mkOption {
        type = attrs;
        default =
          mapAttrs
          (
            _: entry: let
              hasVars = entry ? variables;
              hasApps = entry ? applications;
              hasBinds = entry ? bindings;
              updates =
                optionalAttrs hasBinds {
                  bindings =
                    (mkBindings {
                      inherit (entry) bindings;
                      applications = entry.applications or {};
                    }).options;
                }
                // optionalAttrs hasApps {inherit (entry) applications;}
                // optionalAttrs hasVars {variables = mkRegistryVariables entry;};
            in
              entry // updates
          )
          data;
        readOnly = true;
      });
    };
    registryModules = asListIf hasData [registryModule];
  in {
    imports = (specs.core or []) ++ registryModules;
    home-manager.sharedModules = (specs.home or []) ++ registryModules;
  };

  mkModuleArgs = {
    api ? lib.api or (lix.api or {}),
    config ? {},
    host ? {},
    hostPath ? path,
    extraArgs ? {},
    lib ? {},
    lix ? {},
    options ? {},
    osConfig ? {},
    path,
    pkgs ? {},
    scope ? "core",
    selection ? null,
    top ? null,
    userPath ? path,
    users ? api.users.getInteractiveUsers host,
  }: let
    targets = ["main" "custom" "domain" "parent" "module"];
    # selection = spec: selectionOf {inherit top spec registry;};

    validate = {
      path = target:
        if elem target targets
        then paths.${target}
        else
          throw "Invalid target: '${target}'. Valid targets are: ${
            concatStringsSep ", " targets
          }";
    };

    names =
      genAttrs targets (
        target: let
          check = validate.path target;
        in
          if check != []
          then last check
          else "main"
      )
      // {
        user =
          get.config.main.home.username or (
            get.config.custom.users.primary.name or null
          );
        package = pkg.name or null;
      };

    # pkgName may be a flat string ("gitFull") or a nested path
    # (["llm-agents" "claude-code"]) — normalize to a list either way.
    pkg = let
      name' = get.apiOr "package";
      path' =
        if name' != null
        then asList name'
        else [get.name];
    in {
      path = path';
      name = last path';
      spec = attrByPath path' null pkgs;
    };

    base =
      if top != null
      then top
      else names.custom;

    paths = {
      validate = validate.path;
      main = [];
      custom = [base];
      module = paths.custom ++ path;
      parent = init paths.module;
      domain = paths.custom ++ [(head path)];
    };

    get = {
      inherit host scope names paths users;
      name = names.module;
      prettyName = set.name {pretty = true;};

      user = let
        name = names.user;
      in
        optionalAttrs
        (name != null)
        ((users.${name} or {}) // {inherit name;});

      top =
        if top != null
        then top
        else names.custom;

      config =
        genAttrs targets
        (target: set.config {inherit target;});
      cfg = get.config.module;
      cfgOr = key: let
        fromConfig = attrByPath (paths.module ++ [key]) null config;
      in
        if fromConfig != null
        then fromConfig
        else
          attrByPath
          (paths.module ++ [key]) (extraArgs.${key} or null)
          osConfig;

      options =
        genAttrs targets
        (target: attrByPath (paths.validate target) {} options);

      enabled = {
        criteria ? elem (host.type or "laptop") ["desktop" "laptop"],
        selectFrom ? set.selection,
      }: let
        materialize = selected:
          mapAttrs
          (_: extra: {enable = true;} // extra)
          (foldMerge selected);

        required = let
          byHost = [(selectFrom host)];
          byUser =
            optionals
            criteria
            (map selectFrom (valuesOf users));
        in {
          core = materialize (byHost ++ byUser);
          home =
            materialize
            (byHost ++ (optionals criteria [(selectFrom get.user)]));
        };
      in
        hasAttr get.name required.${scope};

      package = pkg.spec;
      pkgName = pkg.name;
      pkgPath = pkg.path;

      hostEntry = attrByPath hostPath {} host;
      userEntry = attrByPath userPath {} get.user;
      dataEntry = genAttrs targets (
        target: let
          #TODO This is not making use of our target and genAttrs style setup
          domain = head path;
          name = last path;
          registry =
            if target == "module"
            then api.${domain}.registry.${name} or {}
            else if target == "domain"
            then api.${domain}.registry or {}
            else if target == "custom"
            then api.custom.registry or {}
            else if target == "main"
            then api.main.registry or {}
            else {};
        in {
          inherit registry;
          names = namesOf registry;
          values = valuesOf registry;
          select = asAttrs; # TODO: This is not working at all
        }
      );
      apiOr = key:
        get.hostEntry.${key} or
            (get.userEntry.${key} or
              (get.dataEntry.module.registry.${key} or
                (get.dataEntry.parent.registry.${key} or
                  (get.dataEntry.domain.registry.${key} or
                    (get.dataEntry.custom.registry.${key} or
                      (get.dataEntry.main.registry.${key} or null))))));
    };

    set = {
      config = {
        target ? "module",
        extra ? {},
      }: let
        targetPath = paths.validate target;
      in
        attrByPath targetPath {} (
          recursiveUpdate config
          (setAttrByPath targetPath extra)
        );

      options =
        genAttrs
        targets (target: extra: setAttrByPath (paths.validate target) extra);
      opt = set.options.module;

      name = {
        name ? names.module,
        pretty ? true,
      }:
        if pretty
        then toSentenceCase name
        else name;
      enable = {default ? false}:
        mkEnable {
          inherit (get) scope name;
          inherit default;
        };
      package = mkOption {
        type = with types; nullOr package;
        default = get.package;
        description = "Package backing the ${get.prettyName} compositor component.";
      };

      selection = spec:
        if selection != null
        then selection spec
        else asAttrs spec;

      bin = {
        module ? names.module,
        package ? get.package,
      }: let
        name =
          if package != null
          then package.NIX_MAIN_PROGRAM or module
          else null;
        path =
          if package != null
          then "/run/current-system/sw/bin/${module}"
          else null;
      in {inherit package name path;};
    };
  in
    (mkNamespaced {inherit get set;})
    // get
    // {inherit get set;};

  mkCfg = {
    config,
    path,
  }:
    attrByPath (asList path) {} config;

  mkOpt = {
    options,
    path,
  }:
    setAttrByPath (asList path) options;

  mkCfgIf = {
    cfg,
    condition ? cfg.enable or false,
  }: args:
    mkIf condition (
      if isList args
      then mkMerge args
      else args
    );

  mkIf' = cfg: condition: args:
    mkCfgIf {inherit cfg condition;} args;
in
  exports

{
  assembly,
  attrsets,
  lists,
  options,
  types,
  ...
}: let
  exports = {
    scoped = {
      inherit
        mkEnable
        mkAppOptions
        mkAppOption
        mkBindOptions
        mkBindOption
        mkFloatOption
        mkRegistryOptions
        mkLatitudeOption
        mkLongitudeOption
        mkVarOptions
        mkGeoProviderOption
        mkTimezoneOption
        mkLocalTimeOption
        mkLocaleOption
        ;
    };
    global = {};
  };

  inherit (assembly) mkAppBindings mkBindings mkRegistryVariables;
  inherit (attrsets) mapAttrs optionalAttrs recursiveUpdate;
  inherit (lists) hasAny;
  inherit (options) mkOption mkEnableOption;
  inherit
    (types)
    attrsOf
    bool
    nullOr
    addCheck
    either
    float
    isNotEmpty
    listOf
    str
    submodule
    ;

  _defaults = {
    labels = {
      browser = "Browser launch";
      editor = "Editor launch";
      visual = "Visual/IDE launch";
      launcher = "Launcher trigger";
      terminal = "Terminal launch";
    };
  };

  mkEnable = {
    name ? null,
    mod ? null,
    leaf ? null,
    description ? null,
    scope ? "core",
    default ? null,
  }: let
    module =
      if name != null && name != ""
      then name
      else if mod != null && mod != ""
      then mod
      else if leaf != null && leaf != ""
      then leaf
      else null;

    description' =
      if description != null
      then description
      else if module != null
      then "Whether ${module} should be enabled ${
        if scope == "core"
        then "system-wide"
        else if scope == "home"
        then "for the user"
        else throw "Expected scope to be one of [core home], got ${scope}"
      }"
      else "Whether to enable this module";
    mk = condition: mkEnableOption description' // {default = condition;};
  in
    if default != null
    then mk default
    else {
      false = mk false;
      true = mk true;
    };

  mkFloatOption = {
    description,
    min ? null,
    max ? null,
    default ? null,
  }: let
    check = value:
      (
        if min != null
        then value >= min
        else true
      )
      && (
        if max != null
        then value <= max
        else true
      );
  in
    mkOption ({
        type = nullOr (addCheck float check);
        inherit description;
      }
      // optionalAttrs (default != null) {inherit default;});

  mkLatitudeOption = {
    host,
    default ? null,
  }:
    mkFloatOption {
      description = "Latitude coordinate, between -90.0 and 90.0";
      min = -90.0;
      max = 90.0;
      default = host.localization.latitude or default;
    };

  mkLongitudeOption = {
    host,
    default ? null,
  }:
    mkFloatOption {
      description = "Longitude coordinate, between -180.0 and 180.0";
      min = -180.0;
      max = 180.0;
      default = host.localization.longitude or default;
    };

  mkGeoProviderOption = {
    host,
    default ? "manual",
  }: let
    loc = host.localization or {};
    provider = loc.provider or null;
    latitude = loc.latitude or null;
    longitude = loc.longitude or null;
  in
    mkOption {
      type = types.enum ["manual" "geoclue2"];
      description = "Location provider. If 'manual', valid latitude and longitude must be provided.";
      default =
        if provider != null
        then provider
        else if latitude != null && longitude != null
        then default
        else "geoclue2";
    };

  mkTimezoneOption = {
    host,
    default ? null,
  }:
    mkOption ({
        type = nullOr str;
        description = "The system or user timezone.";
      }
      // optionalAttrs (host.localization.timezone or default != null) {
        default = host.localization.timezone or default;
      });

  mkLocalTimeOption = {host}: let
    useLocalTime =
      hasAny
      ["dual-boot" "dualboot-windows"]
      (host.functionalities or []);
  in
    mkEnableOption ''
      Keeps the hardware clock in local time instead of UTC.
      This is particularly important when the system dual-boots with Windows,
      as Windows defaults to local time for the RTC.
    ''
    // {default = useLocalTime;};

  mkLocaleOption = {
    host,
    default ? "en_US.UTF-8",
  }:
    mkOption {
      type = str;
      description = ''
        Configures the default locale settings. This determines:
        - Language for program messages and UI text.
        - Date, time, numeric, and monetary formatting conventions.
        - Character sorting and collation order.

        Applies to all applications that respect locale environment variables.
      '';
      default = host.localization.locale or default;
    };

  # Shared shape for grouping per-item options into one submodule option.
  mkGroupedOptions = {
    name,
    items,
    option,
    description,
  }: {
    ${name} = mkOption {
      inherit description;
      type = submodule {options = mapAttrs (item: _: option item) items;};
      default = {};
    };
  };

  # Shared shape for a single resolved-from-registry option.
  mkRegistryOption = {
    name,
    type,
    label ? null,
    labels ? {},
    prefix,
    noun,
    registry,
  }: let
    labels' = recursiveUpdate _defaults.labels labels;
  in
    mkOption {
      inherit type;
      default = registry.${name} or null;
      description = "${prefix} ${(
        if label != null
        then label
        else (labels'.${name} or "${name} ${noun}")
      )} from the registry.";
    };

  mkRegistryOptions = registry:
    {}
    // optionalAttrs (registry ? variables || registry ? applications)
    (mkVarOptions {variables = mkRegistryVariables registry;})
    // optionalAttrs (registry ? bindings)
    (mkBindOptions {bindings = registry.bindings;})
    // optionalAttrs (registry ? applications)
    (mkAppOptions {applications = registry.applications;});

  mkAppOption = {
    name,
    type ? null,
    label ? null,
    labels ? {},
    applications,
    modifier ? "SUPER",
  }: let
    mod = {
      options = {
        name = mkOption {
          type = str;
          description = "Package name or lookup identifier.";
        };
        description = mkOption {
          type = str;
          description = "Human-readable descriptive label.";
        };
        command = mkOption {
          type = str;
          description = "The executable/binary command used to trigger it.";
        };
        bindings = mkOption {
          type = attrsOf (listOf str);
          default = {};
          description = "Binding keys normalized to list format like { launch = [ 'V' ]; }";
        };
      };
    };
  in
    mkRegistryOption {
      inherit name label labels;
      prefix = "Ordered list of";
      noun = "applications";
      registry = mkAppBindings {inherit applications modifier;};
      type =
        if isNotEmpty type
        then type
        else nullOr (listOf (submodule mod));
    };

  mkAppOptions = {
    applications,
    labels ? {},
    type ? null,
    name ? "applications",
  }:
    mkGroupedOptions {
      inherit name;
      items = applications;
      option = name: mkAppOption {inherit applications labels name type;};
      description = "Priority-ordered tier applications resolved by the registry.";
    };

  mkBindOption = {
    name,
    type ? null,
    label ? null,
    labels ? {},
    bindings,
  }:
    mkRegistryOption {
      inherit name label labels;
      prefix = "Binding key for";
      noun = "binding";
      registry = (mkBindings {inherit bindings;}).options;
      type =
        if isNotEmpty type
        then type
        else either (listOf str) bool;
    };

  mkBindOptions = {
    bindings,
    labels ? {},
    type ? null,
    name ? "bindings",
  }:
    mkGroupedOptions {
      inherit name;
      items = bindings;
      option = itemName:
        mkBindOption {
          inherit bindings labels type;
          name = itemName;
        };
      description = "Hotkey trigger bindings resolved by the registry.";
    };

  mkVarOptions = {
    variables,
    name ? "variables",
    type ? str,
  }:
    mkGroupedOptions {
      inherit name;
      items = variables;
      option = key:
        mkOption {
          inherit type;
          default = variables.${key};
          description = "Variable '${key}' resolved by the registry.";
        };
      description = "Custom configuration variables.";
    };
in
  exports

{
  api,
  debug,
  attrsets,
  lists,
  types,
  flakes,
  strings,
  ...
}: let
  exports = {
    scoped = {
      inherit per classification builder current;
      forEach = per;
      getBuilder = builder;
      getClassification = classification;
    };
    global = {
      forEachSystem = per;
      currentSystem = current;
      systemOf = current;
    };
  };

  inherit (attrsets) attrValues genAttrs;
  inherit (debug) withContext;
  inherit (lists) elem unique;
  inherit (types) isFunction;
  inherit (api) hosts;
  inherit (strings) concat;

  classification = class:
    assert withContext {
      name = "config.systemType";
      assertion = elem class ["nixos" "darwin"];
      message = ''expected one of ["nixos" "darwin"], got ${class}'';
      context = "parsing system type from class";
    };
      if class == "darwin"
      then "darwinConfigurations"
      else "nixosConfigurations";

  builder = class: let
    opts = ["nixos" "darwin"];
  in
    assert withContext {
      name = "config.systemBuilder";
      assertion = elem class opts;
      message = ''expected one of [${concat {
          delim = ", ";
          parts = opts;
        }}], got ${class}'';
      context = "parsing system builder from class";
    };
    with flakes.libraries.default;
      if class == "nixos"
      then nixpkgs.nixosSystem or {}
      else nix-darwin.darwinSystem or {};

  supported = {extra ? []}:
    unique (
      extra
      ++ map (host: host.system or (host.platform or hosts.default.system))
      (attrValues hosts)
    );

  per = arg: let
    opts =
      if isFunction arg
      then {fn = arg;}
      else arg;
    packages = opts.packages or flakes.packages.default;
    extra = opts.extra or [];
  in
    genAttrs
    (supported {inherit extra;})
    (system: opts.fn packages.${system});
  # TODO: add kind (get via parsing input or pkgs.stdenv.hostPlatform) and getOrDefault (via kind or builtins.currentSystem or most common system from api hosts)

  current = pkgs: pkgs.stdenv.hostPlatform.system or builtins.currentSystem;
in
  exports

{
  api,
  attrsets,
  environment,
  lists,
  ...
}: let
  exports = {
    scoped = {
      inherit
        mkSrc
        mkHomeUser
        mkHomeUsers
        mkCoreUsers
        mkSudoRules
        ;
    };
    global = {
      inherit
        mkSrc
        mkHomeUser
        mkHomeUsers
        mkCoreUsers
        mkSudoRules
        ;
    };
  };

  inherit
    (attrsets)
    attrValues
    mapAttrs
    optionalAttrs
    ;
  inherit (api) getEnabledUsers getInteractiveUsers getAdminUsers;
  inherit (environment) mkSrc;
  inherit (lists) asList;

  homeOf = user:
    user.homeDirectory or user.home or "/home/${user.name}";

  mkCoreUsers = host: let
    principals = getEnabledUsers host;

    #| Role-based user classification
    #  administrator → full system access (wheel, networkmanager)
    #  normal        → standard interactive user (networkmanager)
    #  guest         → limited access, no extra groups
    #  service       → system daemon account (no login)
    roleOf = user: user.role or "normal";
    isAdmin = role: role == "administrator";
    isGuest = role: role == "guest";
    isService = role: role == "service";
  in {
    users =
      mapAttrs (_: user: let
        role = roleOf user;
      in {
        inherit (user) description;
        home = homeOf user;
        group = user.group or user.name;

        #| NixOS user type classification
        isNormalUser = !isService role;
        isSystemUser = isService role;

        #| Supplementary groups based on role privileges
        extraGroups =
          if isService role || isGuest role
          then []
          else if isAdmin role
          then ["wheel" "networkmanager"]
          else ["networkmanager"];
      })
      principals;

    groups = mapAttrs (_: _: {}) principals;
  };

  mkHomeUsers = host:
    mapAttrs (
      name: user:
        mkHomeUser {
          inherit name;
          spec = user;
        }
    )
    (getInteractiveUsers host);

  mkHomeUser = {
    name,
    spec,
  }: {osConfig, ...}: {
    imports =
      [
        {
          _module.args.user = spec // {inherit name;};
          programs.home-manager.enable = true;
