  #       args.extraArgs.registry or (
  #         optionalAttrs
  #         (domain != null && api ? ${domain}.registry)
  #         api.${domain}.registry
  #       )
  #   ),
  #   excludes ? null,
  #   extraArgs ? {},
  #   includeFiles ? true,
  #   includes ? [],
  #   path ? [],
  #   childPath ? path,
  #   recurse ? true,
  #   tags ? defaults.tags,
  #   top,
  #   declareRegistry ? isNotEmptyAttr data,
  #   ...
  # }: let
  #   hasData = isNotEmptyAttr data && declareRegistry;
  #   specs = collectSpecs {
  #     inherit args base excludes includes tags includeFiles recurse;
  #     path = childPath;
  #     extraArgs =
  #       recursiveUpdate (args.extraArgs or {}) extraArgs
  #       // optionalAttrs hasData {registry = data;};
  #   };
  #   registryModule = {
  #     options = setAttrByPath ([top] ++ path ++ ["registry"]) (mkOption {
  #       type = attrs;
  #       default =
  #         data
  #         // optionalAttrs (data ? variables || data ? applications)
  #         {variables = mkRegistryVariables data;}
  #         // optionalAttrs (data ? bindings)
  #         {
  #           bindings =
  #             (mkBindings {
  #               inherit (data) bindings;
  #               applications = data.applications or {};
  #             }).options;
  #         }
  #         // optionalAttrs (data ? applications)
  #         {applications = mkAppBindings {inherit (data) applications;};};
  #       readOnly = true;
  #     });
  #   };
  #   registryModules = optionals hasData [registryModule];
  # in {
  #   imports = (specs.core or []) ++ registryModules;
  #   home-manager.sharedModules = (specs.home or []) ++ registryModules;
  # };
in
  exports

{
  attrsets,
  lists,
  debug,
  types,
  ...
}: let
  exports = {
    scoped = {
      inherit nthOr orNull orDefault orEmpty;
      atOr = nthOr;
      has = has';
      hasAny = hasAny';
      isEmpty = isEmpty';
      isNotEmpty = isNotEmpty';
    };
    global = {
      isEmptyList = isEmpty';
      isNotEmptyList = isNotEmpty';
      orDefaultList = orDefault;
      orNullList = orNull;
      valueInList = nthOr;
      inList = has';
      anyInList = hasAny';
    };
  };

  inherit (attrsets) isAttrs;
  inherit (debug) assertWithContext;
  inherit (lists) asList elemAt isList length optionals any elem;
  inherit (types) typeOf isEmpty;

  isEmpty' = value: value == [];
  isNotEmpty' = value: !isEmpty' value;

  # --- Membership Checks ---

  has' = item: list:
    assert assertWithContext {
      name = "lists.has";
      assertion = isList list;
      message = "expected a list to search within, got ${typeOf list}";
      context = "evaluating lists.has";
    };
      elem item list;

  hasAny' = candidates: list:
    assert assertWithContext {
      name = "lists.hasAny";
      assertion = isList list;
      message = "expected a target list to search within, got ${typeOf list}";
      context = "evaluating lists.hasAny";
    };
      any (candidate: elem candidate list) (asList candidates);

  # --- Existing Methods ---

  orNull = value:
    assert assertWithContext {
      name = "lists.orNull";
      assertion = isEmpty value || isList value;
      message = "expected a list, got ${typeOf value}";
      context = "evaluating lists.orNull";
    };
      if isEmpty value || !(isList value)
      then null
      else value;

  orDefault = default: value:
    assert assertWithContext {
      name = "lists.orDefault";
      assertion = isList default && isList value;
      message = "expected lists, got default=${typeOf default} value=${typeOf value}";
      context = "evaluating lists.orDefault";
    };
      if isNotEmpty' value
      then value
      else default;

  orEmpty = value:
    assert assertWithContext {
      name = "lists.orEmpty";
      assertion = value == null || isList value;
      message = "expected a list or null, got ${typeOf value}";
      context = "evaluating lists.orEmpty";
    };
      optionals (isNotEmpty' value) value;

  nthOr = input: let
    fromArgs = {
      position,
      value,
      default ? null,
    }:
      if isList value
      then
        if length value > position
        then elemAt value position
        else default
      else if position == 0
      then value
      else default;
  in
    if isAttrs input
    then fromArgs input
    else
      position:
        fromArgs {
          value = input;
          inherit position;
        };
in
  exports

